    if(el&&el.tagName==='SELECT'){
      el.innerHTML='<option value="">— Non assigné —</option>'+D.chauffeurs.map(d=>`<option value="${E(d.prenom+(d.nom?' '+d.nom:''))}">${E(d.prenom)} ${E(d.nom||'')}</option>`).join('');
    }
