// ── VUE AGENDA DISPATCH ──
let agendaDate = new Date();

const AGENDA_COLORS = {
  nouvelle:'#7c5de8', en_attente:'#f0934a', attribuee:'#5b9cf6',
  acceptee:'#2ecc8a', en_route:'#2ecc8a', sur_place:'#c9a84c',
  onboard:'#2ecc8a', depose:'#5b9cf6', terminee:'#5a5d65',
  facturee:'#5b9cf6', payee:'#2ecc8a', annulee:'#e05c5c', noshow:'#e05c5c'
};

// Couleurs par client — arrivée (pleine) / départ (variante)
const CLIENT_PALETTE = {
  'DUEMEA':     { arr:'#7b5fc8', dep:'#b39ddb', label:'DUEMEA' },
  'MSP':        { arr:'#f0a030', dep:'#ffcc80', label:'MSP' },
  'LVV':        { arr:'#2ecc8a', dep:'#80e8bc', label:'LVV' },
  'DC_GM':      { arr:'#1565c0', dep:'#5b9cf6', label:'DC_GM' },
  'DREAM CASTLE':{ arr:'#1565c0', dep:'#5b9cf6', label:'Dream Castle' },
  'GRAND MAGIC':{ arr:'#1565c0', dep:'#5b9cf6', label:'Grand Magic' },
  'RENFORT MAGICAL':{ arr:'#c0392b', dep:'#e57373', label:'Renfort Magical' },
  'HOTELS DISNEY':{ arr:'#c9a84c', dep:'#f0d080', label:'Hotels Disney' },
  'DELOITTE':   { arr:'#00897b', dep:'#4db6ac', label:'Deloitte' },
  'B&B':        { arr:'#e91e63', dep:'#f48fb1', label:'B&B Hotels' },
  'KTS':        { arr:'#5e35b1', dep:'#9575cd', label:'KTS' },
  'KI SPACE':   { arr:'#00838f', dep:'#4dd0e1', label:'Ki Space' },
  'GLOBAL BUZZ':{ arr:'#2e7d32', dep:'#66bb6a', label:'Global Buzz' },
  'PULLMAN':    { arr:'#37474f', dep:'#78909c', label:'Pullman' },
  'STAYCITY':   { arr:'#6a1b9a', dep:'#ab47bc', label:'Staycity' },
};

// Détecter si c'est une arrivée ou un départ
function isArrival(course) {
  const dep = (course.depart||'').toLowerCase();
  const arr = (course.arrivee||'').toLowerCase();
  const client = (course.client||'').toLowerCase();
  // Arrivée = vient de CDG/Orly/gare vers hôtel/ville
  // Départ = va vers CDG/Orly/gare
  const airports = ['cdg','orly','charles de gaulle','roissy','orly'];
  const gares = ['gare','montparnasse','nord','lyon','st lazare'];
  const isFromAirport = airports.some(a=>dep.includes(a)) || gares.some(g=>dep.includes(g));
  const isToAirport = airports.some(a=>arr.includes(a)) || gares.some(g=>arr.includes(g));
  if(isFromAirport) return true;  // vient de l'aéroport = arrivée
  if(isToAirport) return false;   // va vers l'aéroport = départ
  return true; // défaut arrivée
}

// Couleurs personnalisées choisies par l'admin (chargées depuis Firebase).
// Clé = nom du client en MAJUSCULES, valeur = { arr, dep, label }.
let CUSTOM_CLIENT_COLORS = {};

// Raccourcit un lieu pour l'affichage compact des cartes (agenda, dispatch) :
// reconnaît les lieux fréquents (aéroports, Val d'Europe, gares parisiennes)
// même quand l'adresse complète a été saisie, et les résume à un nom court.
// Fonctionne à l'aller comme au retour (aucune notion de sens dans ce texte).
// Si le lieu n'est pas reconnu, le texte d'origine est renvoyé tel quel
// (mais tronqué s'il est très long, pour ne pas casser la mise en page).
function raccourcirLieu(texte) {
  const t = String(texte||'').trim();
  if(!t) return '—';
  const low = t.toLowerCase();
  if(low.includes('duemea')) return 'DUEMEA';
  if(low.includes('roissy') || low.includes('charles de gaulle') || /\bcdg\b/.test(low)) return 'CDG';
  if(low.includes('orly')) return 'Orly';
  if(low.includes('beauvais')) return 'Beauvais';
  if(low.includes('lvv') || low.includes("val d'europe") || low.includes('val d europe') || low.includes('la vallée village') || low.includes('la vallee village')) return 'LVV';
  if(low.includes('disney') || low.includes('chessy') || low.includes('serris') || low.includes('marne la vallée') || low.includes('marne la vallee')) return 'Disney';
  if(low.includes('gare du nord')) return 'Gare du Nord';
  if(low.includes('gare de lyon')) return 'Gare de Lyon';
  if(low.includes('montparnasse')) return 'Montparnasse';
  if(low.includes('austerlitz')) return 'Austerlitz';
  if(low.includes('paris')) return 'Paris';
  // Lieu non reconnu : on garde le texte saisi, juste raccourci s'il est long
  // (ex: adresse complète) pour ne pas casser l'affichage des cartes.
  return t.length > 24 ? t.slice(0, 22) + '…' : t;
}

function getClientInfo(clientName) {
  const name = (clientName||'').toUpperCase();
  // 1) Correspondance exacte (clé UPPER)
  if(CUSTOM_CLIENT_COLORS[name]) return CUSTOM_CLIENT_COLORS[name];
  // 2) Correspondance NORMALISÉE (accents/pluriel/espaces ignorés) — attrape
  //    le cas d'une course saisie "B&B Hotels" alors que la couleur est stockée
  //    sous "B&B HÔTEL".
  if(typeof _ccNormKey === 'function') {
    const norm = _ccNormKey(name);
    if(norm) {
      for(const [key, val] of Object.entries(CUSTOM_CLIENT_COLORS)) {
        if(_ccNormKey(key) === norm) return val;
      }
    }
  }
  // 3) Correspondance partielle (contient) sur les clés personnalisées
  for(const [key, val] of Object.entries(CUSTOM_CLIENT_COLORS)) {
    if(key && name.includes(key)) return val;
  }
  // 4) Sinon, palette par défaut
  for(const [key, val] of Object.entries(CLIENT_PALETTE)) {
    if(name.includes(key)) return val;
  }
  return { arr:'#7c5de8', dep:'#9e86e8', label:clientName||'—' };
}

// ══════════════ COULEURS PERSONNALISÉES PAR CLIENT ══════════════
// Charge les couleurs enregistrées depuis Firebase (settings/clientColors).
async function loadClientColors() {
  try {
    const rows = await fbGet('settings');
    const row = rows.find(r => r._id === 'clientColors');
    CUSTOM_CLIENT_COLORS = (row && row.data) ? row.data : {};
  } catch(e) { CUSTOM_CLIENT_COLORS = {}; }
}

// CLÉ DE NORMALISATION pour la dédup (accents, casse, espaces, tirets, pluriels).
// Résout "B&B Hôtel" / "B&B Hotels" / "B&B HOTELS" → tous "BBHOTEL"
//        "Dream Castle" / "DreamCastle" → tous "DREAMCASTLE"
//        "Hôtel Deloitte" / "Hotel Deloitte" → tous "HOTELDELOITTE"
function _ccNormKey(name) {
  if (!name) return '';
  let s = String(name).trim().toLowerCase();
  // Retirer les accents (NFD + diacritiques)
  s = s.normalize('NFD').replace(/[̀-ͯ]/g, '');
  // Retirer tout ce qui n'est pas alphanumérique
  s = s.replace(/[^a-z0-9]+/g, '');
  // Retirer un éventuel "s" final (pluriel) si le mot fait > 3 lettres
  if (s.length > 3 && s.endsWith('s')) s = s.slice(0, -1);
  return s.toUpperCase();
}
window._ccNormKey = _ccNormKey;

// Construit la liste fusionnée des clients à colorer, dédupliquée via
// _ccNormKey.
//
// SOURCES AFFICHÉES dans l'éditeur Couleurs par client :
//   1. Vrais clients de Gestion client (D.clients)           → source 'client'
//   2. Couleurs personnalisées saisies ici (CUSTOM_CLIENT_COLORS)
//      qui NE CORRESPONDENT PAS à un client (sinon la fiche l'emporte) → source 'custom'
//
// La palette hardcodée CLIENT_PALETTE ne figure PLUS dans cette liste :
// elle sert uniquement de source de couleurs par défaut dans getClientInfo
// (pour les courses dont le nom client matche une entrée de la palette).
// Résultat : chaque ligne de la liste est supprimable, soit en retirant
// la couleur custom, soit en supprimant la fiche Gestion client.
function ccMergedList() {
  const byKey = new Map(); // normKey → { label, source, upper (clé d'origine) }

  // 1) Couleurs personnalisées (toutes conservées, même si elles ne matchent
  //    pas un client — l'utilisateur les a ajoutées explicitement)
  Object.entries(CUSTOM_CLIENT_COLORS).forEach(([key, v]) => {
    const k = _ccNormKey(key);
    if (!k) return;
    const label = v.label || key;
    byKey.set(k, { label, source: 'custom', upper: String(key).toUpperCase() });
  });

  // 2) Vrais clients de Gestion client — écrase le libellé (priorité absolue
  //    sur le nom propre saisi par l'admin)
  (D.clients || []).forEach(c => {
    if (c && c.nom) {
      const k = _ccNormKey(c.nom);
      if (!k) return;
      byKey.set(k, { label: c.nom, source: 'client', upper: c.nom.toUpperCase() });
    }
  });

  return [...byKey.entries()]
    .map(([normKey, v]) => ({ normKey, upper: v.upper, label: v.label, source: v.source }))
    .sort((a, b) => a.label.localeCompare(b.label, 'fr', { sensitivity: 'base' }));
}

// Affiche l'éditeur de couleurs dans les Paramètres.
function renderClientColors() {
  const wrap = document.getElementById('cc-list');
  if(!wrap) return;
  const list = ccMergedList();

  const doublonsCount = _ccCountDuplicates();
  _ccUpdateClientsDatalist();

  // Bandeau "Nettoyer les doublons" en tête si on en détecte
  const cleanupBanner = doublonsCount > 0
    ? `<div id="cc-cleanup-banner" style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:#fff7ed;border:1px solid #fdba74;border-radius:10px;margin-bottom:10px">
         <div style="flex:1;font-size:12px;color:#9a3412"><b>${doublonsCount}</b> doublon${doublonsCount>1?'s':''} détecté${doublonsCount>1?'s':''} (ex : "B&amp;B Hôtel" / "B&amp;B Hotels"). Fusion automatique = garde le nom de la fiche Gestion client.</div>
         <button class="btn btn-sm" onclick="ccNettoyerDoublons()" style="background:#f97316;color:#fff;border:none;padding:6px 10px;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer">🧹 Fusionner auto</button>
       </div>`
    : '';

  // Barre de sélection multiple : "Tout cocher / Aucun" + "Supprimer sélection"
  const selectBar = `
    <div id="cc-select-bar" style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:var(--card2);border:1px solid var(--border);border-radius:10px;margin-bottom:10px;flex-wrap:wrap">
      <label style="display:flex;align-items:center;gap:6px;font-size:12px;color:var(--muted);cursor:pointer;user-select:none">
        <input type="checkbox" id="cc-select-all" onclick="ccToggleSelectAll(this.checked)" style="width:16px;height:16px;cursor:pointer;accent-color:var(--gold)">
        <b>Tout sélectionner</b>
      </label>
      <span id="cc-sel-count" style="font-size:11px;color:var(--muted);margin-left:auto"><span id="cc-sel-n">0</span> / ${list.length} sélectionné${list.length>1?'s':''}</span>
      <button onclick="ccDeleteSelected()" style="background:#dc2626;color:#fff;border:none;padding:8px 12px;border-radius:8px;font-size:12px;font-weight:700;cursor:pointer;display:flex;align-items:center;gap:6px">🗑️ Supprimer la sélection</button>
    </div>`;

  wrap.innerHTML = cleanupBanner + selectBar + list.map(({ normKey, upper, label, source }) => {
    const info = getClientInfo(label);
    const custom = CUSTOM_CLIENT_COLORS[upper]
                || CUSTOM_CLIENT_COLORS[label.toUpperCase()]
                || _ccFindCustomByNorm(normKey);
    const arr = (custom && custom.arr) || info.arr;
    const dep = (custom && custom.dep) || info.dep;
    const isCustom = !!custom;
    const srcBadge = source === 'client'
      ? ' <span title="Depuis Gestion client" style="color:#4a9eff;font-size:10px">●</span>'
      : (isCustom ? ' <span title="Couleur personnalisée" style="color:var(--green);font-size:10px">●</span>' : '');
    return `<div style="display:flex;align-items:center;gap:10px;padding:8px 0;border-bottom:1px solid var(--border)" data-cc-norm="${normKey}" data-cc-name="${label.replace(/"/g,'&quot;').toUpperCase()}" data-cc-label="${label.replace(/"/g,'&quot;')}" data-cc-source="${source}">
      <input type="checkbox" class="cc-chk" onchange="ccUpdateSelCount()" style="width:16px;height:16px;cursor:pointer;accent-color:var(--gold);flex-shrink:0">
      <div style="flex:1;font-size:13px;font-weight:600">${E(label)}${srcBadge}</div>
      <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--muted)">🛬 Arrivée
        <input type="color" class="cc-arr" value="${arr}" style="width:34px;height:28px;border:none;background:none;cursor:pointer;padding:0">
      </label>
      <label style="display:flex;align-items:center;gap:4px;font-size:11px;color:var(--muted)">🛫 Départ
        <input type="color" class="cc-dep" value="${dep}" style="width:34px;height:28px;border:none;background:none;cursor:pointer;padding:0">
      </label>
      <button title="Supprimer cette entrée" onclick="ccRemoveEntryFull('${normKey}')" style="background:transparent;border:none;color:#e05c5c;cursor:pointer;padding:4px 6px;font-size:14px">🗑️</button>
    </div>`;
  }).join('');

  ccUpdateSelCount();
}

// Coche / décoche TOUTES les cases d'un coup
window.ccToggleSelectAll = function(checked) {
  document.querySelectorAll('#cc-list .cc-chk').forEach(ch => { ch.checked = checked; });
  ccUpdateSelCount();
};

// Met à jour le compteur "X / Y sélectionné"
window.ccUpdateSelCount = function() {
  const chks = document.querySelectorAll('#cc-list .cc-chk');
  const cocheees = [...chks].filter(c => c.checked).length;
  const el = document.getElementById('cc-sel-n');
  if(el) el.textContent = cocheees;
  const all = document.getElementById('cc-select-all');
  if(all) {
    all.checked = (cocheees === chks.length && chks.length > 0);
    all.indeterminate = (cocheees > 0 && cocheees < chks.length);
  }
};

// Supprime TOUTES les entrées cochées :
//  - couleur personnalisée dans CUSTOM_CLIENT_COLORS
//  - FICHE CLIENT dans D.clients (si l'entrée vient de Gestion client)
// Avec confirmation détaillée de ce qui va être supprimé.
window.ccDeleteSelected = async function() {
  const rows = [...document.querySelectorAll('#cc-list [data-cc-norm]')]
    .filter(r => r.querySelector('.cc-chk')?.checked);
  if(!rows.length) { showToast('Rien de sélectionné', true); return; }

  // Prépare la liste des choses à supprimer
  const aSupprimer = rows.map(r => ({
    norm:   r.getAttribute('data-cc-norm'),
    label:  r.getAttribute('data-cc-label'),
    upper:  r.getAttribute('data-cc-name'),
    source: r.getAttribute('data-cc-source'),
  }));

  // Détaille ce qui sera touché pour la confirmation
  const nbCouleurs = aSupprimer.length;
  const fichesClient = aSupprimer.filter(a => a.source === 'client');
  const nbFiches = fichesClient.length;

  let msg = `Supprimer ${nbCouleurs} entrée${nbCouleurs>1?'s':''} ?\n\n`;
  msg += aSupprimer.map(a => '• ' + a.label + (a.source==='client' ? '  (fiche Gestion client)' : '')).join('\n');
  if(nbFiches > 0) {
    msg += `\n\n⚠️ ATTENTION : ${nbFiches} fiche${nbFiches>1?'s':''} de Gestion client sera${nbFiches>1?'ont':''} supprimée${nbFiches>1?'s':''}.`;
    msg += `\nLes courses déjà enregistrées au nom de ce${nbFiches>1?'s':''} client${nbFiches>1?'s':''} ne sont PAS touchées.`;
  }

  if(!confirm(msg)) return;

  let okCouleurs = 0, okFiches = 0, errors = 0;

  // 1) Supprime dans CUSTOM_CLIENT_COLORS (en mémoire + Firebase à la fin)
  for(const a of aSupprimer) {
    let found = false;
    for(const key of Object.keys(CUSTOM_CLIENT_COLORS)) {
      if(_ccNormKey(key) === a.norm) {
        delete CUSTOM_CLIENT_COLORS[key];
        found = true;
      }
    }
    if(found) okCouleurs++;
  }
  try {
    await fbUpdate('settings', 'clientColors', { data: CUSTOM_CLIENT_COLORS });
  } catch(e) { errors++; }

  // 2) Supprime les fiches D.clients qui correspondent (même clé normalisée)
  for(const a of aSupprimer) {
    const fiches = (D.clients || []).filter(c => c && c.nom && _ccNormKey(c.nom) === a.norm);
    for(const fiche of fiches) {
      if(!fiche._id) continue;
      try {
        await fbDelete('clients', fiche._id);
        okFiches++;
      } catch(e) { errors++; }
    }
  }

  // Recharge et ré-affiche
  if(typeof loadAll === 'function') try { await loadAll(); } catch(e){}
  renderClientColors();

  // Toast récapitulatif
  const parts = [];
  if(okCouleurs) parts.push(okCouleurs + ' couleur' + (okCouleurs>1?'s':''));
  if(okFiches)   parts.push(okFiches   + ' fiche'   + (okFiches>1?'s':''));
  const resume = parts.join(' + ') || '0';
  showToast('✓ Supprimé : ' + resume + (errors ? ' (' + errors + ' erreurs)' : ''), errors > 0);
};

// Suppression UNITAIRE (bouton 🗑️ sur une ligne) : supprime la couleur ET,
// si l'entrée vient de Gestion client, propose aussi de supprimer la fiche.
window.ccRemoveEntryFull = async function(normKey) {
  if(!normKey) return;
  const list = ccMergedList();
  const entry = list.find(e => e.normKey === normKey);
  if(!entry) { showToast('Entrée introuvable', true); return; }

  let msg = 'Supprimer "' + entry.label + '" ?';
  const fiches = (D.clients || []).filter(c => c && c.nom && _ccNormKey(c.nom) === normKey);
  if(fiches.length) {
    msg += `\n\n⚠️ Cela supprimera aussi la fiche ${fiches.length>1?'des '+fiches.length+' clients':'du client'} dans Gestion client.`;
    msg += `\nLes courses déjà enregistrées ne sont PAS touchées.`;
  }
  if(!confirm(msg)) return;

  // Supprime la couleur
  for(const key of Object.keys(CUSTOM_CLIENT_COLORS)) {
    if(_ccNormKey(key) === normKey) delete CUSTOM_CLIENT_COLORS[key];
  }
  try { await fbUpdate('settings', 'clientColors', { data: CUSTOM_CLIENT_COLORS }); } catch(e){}
  // Supprime la ou les fiches clients correspondantes
  for(const fiche of fiches) {
    if(!fiche._id) continue;
    try { await fbDelete('clients', fiche._id); } catch(e){}
  }

  if(typeof loadAll === 'function') try { await loadAll(); } catch(e){}
  renderClientColors();
  showToast('✓ Supprimé');
};

// Cherche une couleur personnalisée par sa clé NORMALISÉE (accents/plurals/
// espaces ignorés). Utile pour retrouver "B&B HOTELS" quand on cherche
// "B&B HÔTEL".
function _ccFindCustomByNorm(normKey) {
  if(!normKey) return null;
  for(const [key, val] of Object.entries(CUSTOM_CLIENT_COLORS)) {
    if(_ccNormKey(key) === normKey) return val;
  }
  return null;
}

// Compte le nombre d'entrées EN TROP dans CUSTOM_CLIENT_COLORS (doublons
// qui se regroupent sur la même clé normalisée).
function _ccCountDuplicates() {
  const groups = {};
  for(const key of Object.keys(CUSTOM_CLIENT_COLORS)) {
    const k = _ccNormKey(key);
    if(!k) continue;
    groups[k] = (groups[k]||0) + 1;
  }
  let dupes = 0;
  for(const n of Object.values(groups)) if(n > 1) dupes += (n - 1);
  return dupes;
}

// Alimente / met à jour la datalist attachée au champ "cc-new-name".
function _ccUpdateClientsDatalist() {
  const inp = document.getElementById('cc-new-name');
  if(!inp) return;
  let dl = document.getElementById('cc-clients-datalist');
  if(!dl) {
    dl = document.createElement('datalist');
    dl.id = 'cc-clients-datalist';
    inp.setAttribute('list', 'cc-clients-datalist');
    inp.parentNode.appendChild(dl);
  }
  // Suggestions = tous les clients de Gestion client qui n'ont PAS déjà
  // une entrée couleur (via la clé normalisée).
  const existingNorms = new Set();
  Object.keys(CUSTOM_CLIENT_COLORS).forEach(k => existingNorms.add(_ccNormKey(k)));
  Object.keys(CLIENT_PALETTE).forEach(k => existingNorms.add(_ccNormKey(k)));
  const suggestions = (D.clients||[])
    .filter(c => c && c.nom && !existingNorms.has(_ccNormKey(c.nom)))
    .map(c => c.nom)
    .sort((a,b)=>a.localeCompare(b,'fr',{sensitivity:'base'}));
  dl.innerHTML = suggestions.map(n => `<option value="${E(n)}">`).join('');
}

// Retire une entrée (par clé normalisée) de CUSTOM_CLIENT_COLORS et
// sauvegarde. Les entrées venant de Gestion client ne peuvent pas être
// retirées depuis ici (utiliser Gestion client).
window.ccRemoveEntry = async function(normKey) {
  if(!normKey) return;
  if(!confirm('Retirer cette couleur personnalisée ? (La fiche client reste)')) return;
  let changed = false;
  for(const key of Object.keys(CUSTOM_CLIENT_COLORS)) {
    if(_ccNormKey(key) === normKey) {
      delete CUSTOM_CLIENT_COLORS[key];
      changed = true;
    }
  }
  if(!changed) { showToast('Rien à retirer', true); renderClientColors(); return; }
  try {
    await fbUpdate('settings', 'clientColors', { data: CUSTOM_CLIENT_COLORS });
    showToast('Entrée retirée ✓');
  } catch(e) { showToast('Erreur enregistrement', true); }
  renderClientColors();
};

// Nettoie TOUS les doublons de CUSTOM_CLIENT_COLORS :
//   - Groupe les clés par leur forme normalisée (_ccNormKey)
//   - Pour chaque groupe à plusieurs entrées :
//     • Choisit la "meilleure" clé (celle qui matche un client de D.clients
//       en priorité, sinon la plus récente / avec le label le plus riche)
//     • Fusionne les couleurs (garde la 1re arr/dep non vide dans l'ordre
//       de priorité ci-dessus)
//     • Supprime les autres
//   - Sauvegarde dans Firebase
window.ccNettoyerDoublons = async function() {
  const dupes = _ccCountDuplicates();
  if(!dupes) { showToast('Aucun doublon à nettoyer'); return; }
  if(!confirm(`Fusionner les ${dupes} doublon${dupes>1?'s':''} ? Les couleurs du client enregistré en Gestion client sont gardées en priorité.`)) return;

  // Index des clients de Gestion client par clé normalisée
  const clientsByNorm = {};
  (D.clients||[]).forEach(c => {
    if(c && c.nom) clientsByNorm[_ccNormKey(c.nom)] = c.nom;
  });

  // Regroupe les entrées CUSTOM_CLIENT_COLORS par clé normalisée
  const groups = {};
  for(const [key, val] of Object.entries(CUSTOM_CLIENT_COLORS)) {
    const k = _ccNormKey(key);
    if(!k) continue;
    (groups[k] = groups[k] || []).push({ key, val });
  }

  const nouveau = {};
  let fusions = 0;
  for(const [normKey, entries] of Object.entries(groups)) {
    // Détermine le "label" final : priorité à Gestion client
    const labelClient = clientsByNorm[normKey];
    // Entrée fusionnée : prend arr/dep de la 1re entrée (toutes présentes), label intelligent
    const merged = { arr: '', dep: '', label: '' };
    for(const e of entries) {
      if(!merged.arr && e.val && e.val.arr) merged.arr = e.val.arr;
      if(!merged.dep && e.val && e.val.dep) merged.dep = e.val.dep;
    }
    // Label : nom de Gestion client sinon celui qui a le plus de caractères "humains"
    //   (espaces/accents/majuscules signalent un vrai libellé par rapport à "BBHOTELS")
    if(labelClient) {
      merged.label = labelClient;
    } else {
      merged.label = entries
        .map(e => (e.val && e.val.label) || e.key)
        .sort((a,b) => {
          const aHuman = /[\sÀ-ÿ&-]/.test(a) ? 1 : 0;
          const bHuman = /[\sÀ-ÿ&-]/.test(b) ? 1 : 0;
          if(aHuman !== bHuman) return bHuman - aHuman;
          return b.length - a.length;
        })[0] || entries[0].key;
    }
    // Clé finale = label en majuscules (compatibilité avec les accès UPPER existants)
    const finalKey = merged.label.toUpperCase();
    // Si plusieurs entrées pointaient vers la même clé normalisée, c'est une fusion
    if(entries.length > 1) fusions += (entries.length - 1);
    nouveau[finalKey] = merged;
  }

  CUSTOM_CLIENT_COLORS = nouveau;
  try {
    await fbUpdate('settings', 'clientColors', { data: CUSTOM_CLIENT_COLORS });
    showToast(`✓ ${fusions} doublon${fusions>1?'s':''} fusionné${fusions>1?'s':''}`);
  } catch(e) { showToast('Erreur enregistrement', true); }
  renderClientColors();
  // Rafraîchir aussi les cartes/listes de courses qui utilisent getClientInfo
  if(typeof loadAll === 'function') try { await loadAll(); } catch(e){}
};

// Ajoute un nouveau client dans la liste (non enregistré tant qu'on ne clique
// pas Enregistrer). Si un client avec la MÊME clé normalisée existe déjà
// (accents/majuscules/pluriel ignorés), on n'en recrée pas un en plus.
function ccAddClient() {
  const inp = document.getElementById('cc-new-name');
  const rawName = (inp.value||'').trim();
  if(!rawName) { showToast('Entrez un nom de client', true); return; }
  const normKey = _ccNormKey(rawName);
  // Déjà présent (quelle que soit la source) ?
  const dejaPresent = ccMergedList().some(e => e.normKey === normKey);
  if(dejaPresent) {
    showToast('Ce client existe déjà dans la liste', true);
    inp.value = '';
    return;
  }
  const upperName = rawName.toUpperCase();
  const info = getClientInfo(rawName);
  CUSTOM_CLIENT_COLORS[upperName] = { arr: info.arr, dep: info.dep, label: rawName };
  inp.value = '';
  renderClientColors();
}

// Enregistre toutes les couleurs de l'éditeur dans Firebase.
// Utilise le libellé (data-cc-label) comme clé UPPER pour éviter de ré-introduire
// des doublons entre "B&B HOTEL" et "B&B HOTELS" si deux lignes avaient le même
// nom normalisé — la dernière ligne lue gagne.
async function saveClientColors() {
  const rows = document.querySelectorAll('#cc-list [data-cc-norm]');
  // D'abord, on ne garde que les clients de D.clients déjà indexés par leur nom propre
  const clientsByNorm = {};
  (D.clients||[]).forEach(c => {
    if(c && c.nom) clientsByNorm[_ccNormKey(c.nom)] = c.nom;
  });
  const data = {};
  const vus = new Set();
  rows.forEach(row => {
    const norm  = row.getAttribute('data-cc-norm') || '';
    const label = row.getAttribute('data-cc-label') || '';
    // Si déjà un client officiel pour cette clé, on utilise SON nom (bonne casse)
    const finalLabel = clientsByNorm[norm] || label;
    const finalKey = finalLabel.toUpperCase();
    if(vus.has(norm)) return; // dédup au cas où
    vus.add(norm);
    const arr = row.querySelector('.cc-arr')?.value;
    const dep = row.querySelector('.cc-dep')?.value;
    if(arr && dep) data[finalKey] = { arr, dep, label: finalLabel };
  });
  try {
    await fbUpdate('settings', 'clientColors', { data });
    CUSTOM_CLIENT_COLORS = data;
    showToast('Couleurs enregistrées ✓');
    if(typeof loadAll === 'function') await loadAll();
  } catch(e) { showToast('Erreur d\'enregistrement', true); }
}

function getClientColor(clientName, course) {
  const info = getClientInfo(clientName);
  if(!course) return info.arr;
  return isArrival(course) ? info.arr : info.dep;
}

// ★ Calcule la couleur de texte lisible (noir ou blanc) selon la couleur de fond.
// Formule standard W3C de luminosité perçue (0 = noir, 1 = blanc).
// Seuil ~0.55 : au-dessus = fond clair → texte noir ; au-dessous = fond sombre → texte blanc.
function texteLisible(bgColor) {
  if(!bgColor) return '#111';
  var hex = String(bgColor).trim();
  if(hex.charAt(0) === '#') hex = hex.slice(1);
  if(hex.length === 3) hex = hex[0]+hex[0]+hex[1]+hex[1]+hex[2]+hex[2];
  if(hex.length !== 6) return '#111';
  var r = parseInt(hex.slice(0,2),16)/255;
  var g = parseInt(hex.slice(2,4),16)/255;
  var b = parseInt(hex.slice(4,6),16)/255;
  // Pondération perceptuelle (yeux humains plus sensibles au vert)
  var luminance = 0.299*r + 0.587*g + 0.114*b;
  return luminance > 0.55 ? '#111' : '#fff';
}

// ★ Couleur de badge/accent translucide, teinte opposée au texte pour contraste.
function badgeContraste(bgColor) {
  return texteLisible(bgColor) === '#111' ? 'rgba(0,0,0,0.14)' : 'rgba(255,255,255,0.28)';
}

function getDirectionIcon(course) {
  return isArrival(course) ? '🛬' : '🛫';
}


window.switchDispatchView = function(view) {
  const agenda = document.getElementById('dv-planning-agenda');
  const table = document.getElementById('dv-planning-table');
  if(view === 'agenda') {
    if(agenda) agenda.style.display = 'block';
    if(table) table.style.display = 'none';
    renderAgenda();
  } else {
    if(agenda) agenda.style.display = 'none';
    if(table) table.style.display = 'block';
    renderDispatch();
  }
};

window.agendaDay = function(d) { agendaDate.setDate(agendaDate.getDate()+d); renderAgenda(); };
window.agendaToday = function() { agendaDate = new Date(); renderAgenda(); };

function renderAgenda() {
  const today = new Date();
  const sel = agendaDate;
  // Date locale (France) au format YYYY-MM-DD — PAS toISOString() qui donne l'UTC
  // et peut decaler d'un jour en soiree (ex: 30 aout 00h30 -> 29 aout UTC).
  const _ymdLocal = (dt) => {
    const y = dt.getFullYear();
    const m = String(dt.getMonth()+1).padStart(2,'0');
    const d = String(dt.getDate()).padStart(2,'0');
    return `${y}-${m}-${d}`;
  };
  const selStr = _ymdLocal(sel);

  // Date title
  const titleEl = document.getElementById('agenda-date-title');
  if(titleEl) {
    const isToday = sel.toDateString() === today.toDateString();
    titleEl.textContent = (isToday ? 'Aujourd\'hui — ' : '') +
      sel.toLocaleDateString('fr-FR', {weekday:'long', day:'numeric', month:'long', year:'numeric'});
  }

  // Week strip — 7 days centered on selected
  const strip = document.getElementById('agenda-week-strip');
  if(strip) {
    const days = [];
    for(let i=-3; i<=3; i++) {
      const d = new Date(sel); d.setDate(sel.getDate()+i);
      days.push(d);
    }
    const jours = ['D','L','M','M','J','V','S'];
    strip.innerHTML = days.map(d => {
      const ds = d.toISOString().split('T')[0];
      const isToday = d.toDateString() === today.toDateString();
      const isSel = d.toDateString() === sel.toDateString();
      const dayCourses = D.courses.filter(c=>c.datetime&&c.datetime.startsWith(ds)&&!['terminee','annulee','noshow','payee'].includes(c.statut));
      const dots = dayCourses.slice(0,4).map(c=>`<div class="dot" style="background:${getClientColor(c.client,c)}"></div>`).join('');
      return `<div class="week-day ${isToday?'today':''} ${isSel?'selected':''}" onclick="agendaDate=new Date('${ds}');renderAgenda()">
        <div class="dn">${jours[d.getDay()]}</div>
        <div class="dd">${d.getDate()}</div>
        <div class="dots">${dots}</div>
      </div>`;
    }).join('');
  }

  // ★ RECHERCHE : chauffeur, client ou passager (nom, prénom, morceau de nom).
  // Quand un texte est saisi, on cherche sur TOUTES les dates (pas seulement le
  // jour affiché) : à venir d'abord (du plus proche au plus lointain), puis les
  // transferts passés (du plus récent au plus ancien).
  const _rq = agendaNormRech(window.agendaRecherche || '');
  let toutesCourses;
  if (_rq) {
    const mots = _rq.split(' ').filter(Boolean);
    const auj = new Date(); auj.setMinutes(auj.getMinutes() - auj.getTimezoneOffset());
    const aujStr = auj.toISOString().slice(0,10);
    const trouvees = D.courses.filter(c => c && c.datetime && agendaCourseCorrespond(c, mots));
    const aVenir = trouvees.filter(c => c.datetime.slice(0,10) >= aujStr).sort((a,b)=>a.datetime.localeCompare(b.datetime));
    const passees = trouvees.filter(c => c.datetime.slice(0,10) < aujStr).sort((a,b)=>b.datetime.localeCompare(a.datetime));
    toutesCourses = aVenir.concat(passees).slice(0, 300);
    window._agendaRechPassesDes = aVenir.length;
  } else {
    toutesCourses = D.courses.filter(c=>c.datetime&&c.datetime.startsWith(selStr))
      .sort((a,b)=>a.datetime.localeCompare(b.datetime));
  }

  // Filtre "Non attribués" (toggle via le bouton à côté du compteur)
  const filtreNonAttribue = !!window.agendaFiltreNonAttribue;
  const courses = filtreNonAttribue
    ? toutesCourses.filter(c => !c.chauffeur && !c.chauffeurUid)
    : toutesCourses;

  const nbTotal = toutesCourses.length;
  const nbNonAttribues = toutesCourses.filter(c => !c.chauffeur && !c.chauffeurUid).length;

  const cnt = document.getElementById('agenda-cnt');
  if(cnt) {
    if (_rq) {
      cnt.textContent = `${courses.length} résultat${courses.length!==1?'s':''}` + (filtreNonAttribue ? ' à attribuer' : '');
    } else if (filtreNonAttribue) {
      cnt.textContent = `${courses.length} / ${nbTotal} à attribuer`;
    } else {
      cnt.textContent = `${nbTotal} course${nbTotal!==1?'s':''}`;
    }
  }

  // Injection du bouton toggle à côté du compteur (une seule fois)
  if (cnt && !document.getElementById('agenda-filter-btn')) {
    const btn = document.createElement('button');
    btn.id = 'agenda-filter-btn';
    btn.className = 'btn btn-ghost btn-sm';
    btn.style.cssText = 'margin-left:4px;font-size:12px;padding:6px 12px';
    btn.setAttribute('title', 'Afficher seulement les transferts non attribués à un chauffeur');
    btn.onclick = function(){
      window.agendaFiltreNonAttribue = !window.agendaFiltreNonAttribue;
      renderAgenda();
    };
    cnt.insertAdjacentElement('afterend', btn);
  }
  // ★ Bouton SUPPRIMER (injecté une seule fois à côté de "À attribuer") —
  // supprime les courses sélectionnées via les cases à cocher. Double
  // confirmation obligatoire pour éviter toute erreur irréversible.
  if (cnt && !document.getElementById('agenda-delete-btn')) {
    const btnDel = document.createElement('button');
    btnDel.id = 'agenda-delete-btn';
    btnDel.className = 'btn btn-sm';
    btnDel.style.cssText = 'margin-left:4px;font-size:12px;padding:6px 12px;background:#fee2e2;color:#991b1b;border:1px solid #fca5a5;font-weight:700;cursor:pointer';
    btnDel.setAttribute('title', 'Supprimer les courses sélectionnées (double confirmation)');
    btnDel.innerHTML = '<i class="fas fa-trash"></i> Supprimer';
    btnDel.onclick = function(){ try { supprimerCoursesSelectionnees(); } catch(e){ console.warn(e); } };
    const filterBtn = document.getElementById('agenda-filter-btn');
    if (filterBtn) filterBtn.insertAdjacentElement('afterend', btnDel);
    else cnt.insertAdjacentElement('afterend', btnDel);
  }
  // ★ Barre de RECHERCHE (injectée une seule fois, à côté de « Supprimer »).
  // Elle n'est jamais redessinée : le clavier reste ouvert pendant la saisie.
  if (cnt && !document.getElementById('agenda-search-wrap')) {
    const w = document.createElement('div');
    w.id = 'agenda-search-wrap';
    w.style.cssText = 'position:relative;flex:1 1 240px;min-width:200px;max-width:420px;margin-left:4px';
    w.innerHTML = '<i class="fas fa-search" aria-hidden="true" style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:var(--muted);font-size:13px;pointer-events:none"></i>'
      + '<input type="text" enterkeyhint="search" id="agenda-search" placeholder="Chauffeur, client ou passager…" autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" maxlength="80" aria-label="Rechercher un chauffeur, un client ou un passager"'
      + ' style="width:100%;box-sizing:border-box;padding:8px 34px 8px 34px;border:1px solid var(--border2);border-radius:8px;background:var(--card);color:var(--white);font-size:16px;outline:none">'
      + '<button type="button" id="agenda-search-clear" aria-label="Effacer la recherche" style="display:none;position:absolute;right:4px;top:50%;transform:translateY(-50%);background:none;border:none;color:var(--muted);font-size:16px;padding:6px 8px;cursor:pointer">✕</button>';
    const ancre = document.getElementById('agenda-delete-btn') || document.getElementById('agenda-filter-btn') || cnt;
    ancre.insertAdjacentElement('afterend', w);
    const inp = w.querySelector('#agenda-search'), clr = w.querySelector('#agenda-search-clear');
    inp.value = window.agendaRecherche || '';
    let _t = null;
    const lancer = function(){
      window.agendaRecherche = inp.value;
      clr.style.display = inp.value ? '' : 'none';
      clearTimeout(_t);
      _t = setTimeout(function(){ try { renderAgenda(); } catch(e){ console.warn(e); } }, 150);
    };
    inp.addEventListener('input', lancer);
    inp.addEventListener('keydown', function(e){ if (e.key === 'Escape') { inp.value = ''; lancer(); } });
    clr.addEventListener('click', function(){ inp.value = ''; lancer(); inp.focus(); });
    clr.style.display = inp.value ? '' : 'none';
  }
  // Pendant une recherche, la semaine et les flèches ne filtrent plus : on le montre.
  try {
    const wk = document.getElementById('agenda-week-strip');
    if (wk) wk.style.opacity = _rq ? '0.35' : '';
  } catch(e){}

  // Mise à jour du texte et style du bouton (reflet de l'état)
  const btnF = document.getElementById('agenda-filter-btn');
  if (btnF) {
    if (filtreNonAttribue) {
      btnF.innerHTML = '<i class="fas fa-eye"></i> Voir tout';
      btnF.style.background = '#fff3cd';
      btnF.style.color = '#856404';
      btnF.style.border = '1px solid #ffc107';
    } else {
      const badge = nbNonAttribues > 0
        ? ' <span style="background:#dc3545;color:#fff;border-radius:10px;padding:1px 6px;font-size:10px;font-weight:700;margin-left:4px">'+nbNonAttribues+'</span>'
        : '';
      btnF.innerHTML = '<i class="fas fa-user-slash"></i> À attribuer' + badge;
      btnF.style.background = '';
      btnF.style.color = '';
      btnF.style.border = '';
    }
  }

  const list = document.getElementById('agenda-list');
  if(!list) return;

  if(!courses.length && _rq) {
    list.innerHTML = `<div style="text-align:center;padding:50px 20px;color:var(--muted)">
      <i class="fas fa-search" style="font-size:40px;opacity:0.3;display:block;margin-bottom:12px"></i>
      <div style="font-family:'Inter',sans-serif;font-size:16px;font-weight:700;margin-bottom:4px">Aucun transfert trouvé</div>
      <div style="font-size:13px">pour « ${E(window.agendaRecherche||'')} »${filtreNonAttribue?' parmi les transferts à attribuer':''}</div>
      <button class="btn btn-ghost btn-sm" style="margin-top:16px" onclick="agendaRechercheEffacer()"><i class="fas fa-times"></i> Effacer la recherche</button>
    </div>`;
    return;
  }
  if(!courses.length) {
    list.innerHTML = `<div style="text-align:center;padding:60px 20px;color:var(--muted)">
      <i class="fas fa-calendar-check" style="font-size:48px;opacity:0.3;display:block;margin-bottom:12px"></i>
      <div style="font-family:'Inter',sans-serif;font-size:16px;font-weight:700;margin-bottom:4px">Aucune course</div>
      <div style="font-size:12px">Pas de transfert planifié pour cette journée</div>
      <button class="btn btn-p btn-sm" style="margin-top:16px" onclick="openCourseModal()"><i class="fas fa-plus"></i> Ajouter une course</button>
    </div>`;
    return;
  }

  // Legende : la liste des noms de clients a ete retiree (demande dispatch,
  // elle occupait plusieurs lignes sans servir a l'exploitation).
  const legendHtml = `
  <!-- Barre sélection groupe -->
  <div id="agenda-groupe-bar" style="display:none;margin-bottom:12px;padding:10px 14px;background:var(--purple-dim);border:1px solid rgba(155,127,240,0.3);border-radius:var(--r-sm);align-items:center;gap:10px;flex-wrap:wrap">
    <span style="font-size:12px;color:var(--purple);font-weight:600"><i class="fas fa-check-square"></i> <span id="agenda-sel-count">0</span> course(s) sélectionnée(s)</span>
    <div class="drv-wrap" style="min-width:220px">
      <input type="text" id="agenda-drv-input" class="drv-input" placeholder="Rechercher un chauffeur..." autocomplete="off"
        oninput="filterDrv('agenda-drv',this.value)" onfocus="openDrv('agenda-drv')" onblur="setTimeout(()=>closeDrv('agenda-drv'),200)" maxlength="200">
      <input type="hidden" id="agenda-drv" value="">
      <div class="drv-drop" id="drv-drop-agenda-drv"></div>
    </div>
    <button class="btn btn-p btn-sm" onclick="assignAgendaGroupe()"><i class="fas fa-user-check"></i> Assigner le groupe</button>
    <button class="btn btn-sm" onclick="proposerGroupeAuxPrioritaires()" style="background:linear-gradient(135deg,#fef3c7,#fde68a);border:1px solid #d97706;color:#92400e;font-weight:700" title="Envoyer les courses sélectionnées aux chauffeurs ⭐ prioritaires">⭐ Prioritaires</button>
    <button class="btn btn-sm" onclick="proposerGroupeATous()" style="background:linear-gradient(135deg,#fffbeb,#fef3c7);border:1px solid #f59e0b;color:#b45309;font-weight:700" title="Envoyer les courses sélectionnées à TOUS les chauffeurs — le premier qui accepte garde">🙋 À tous</button>
    <button class="btn btn-ghost btn-sm" onclick="clearAgendaSelection()"><i class="fas fa-times"></i> Annuler</button>
  </div>
  <!-- Légende + sélection tout -->
  <div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:8px;margin-bottom:12px">
    <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">
      <label style="display:flex;align-items:center;gap:5px;font-size:11px;cursor:pointer;color:var(--muted2)">
        <input type="checkbox" id="agenda-chk-all" onchange="agendaToggleAll(this)" style="width:14px;height:14px;cursor:pointer">
        Tout sélectionner
      </label>
    </div>
    <div style="display:flex;align-items:center;gap:10px">
      <span style="font-size:15px">🛬</span><span style="font-size:14px;color:var(--muted)">Arrivée</span>
      <span style="font-size:15px">🛫</span><span style="font-size:14px;color:var(--muted)">Départ</span>
    </div>
  </div>`;

  // Style Google Agenda — blocs colorés pleins, empilés
  let _jourPrec = '';
  list.innerHTML = legendHtml + courses.map((c, _i) => {
   let _entete = '';
   if (_rq) {
     const j = (c.datetime||'').slice(0,10);
     if (_i === (window._agendaRechPassesDes||0) && _i > 0) _entete += '<div style="margin:18px 0 6px;font-size:12px;font-weight:800;color:var(--muted);text-transform:uppercase;letter-spacing:0.5px;border-top:1px solid var(--border2);padding-top:12px">Transferts passés</div>';
     if (j !== _jourPrec) {
       _jourPrec = j;
       let lib = j;
       try { lib = new Date(j + 'T12:00:00').toLocaleDateString('fr-FR', { weekday:'long', day:'numeric', month:'long', year:'numeric' }); } catch(e){}
       _entete += '<div style="margin:12px 0 6px;font-size:13px;font-weight:700;color:var(--white);text-transform:capitalize">' + E(lib) + '</div>';
     }
   }
   return _entete + (function(){
   try {
    const color = getClientColor(c.client, c);
    const time = c.datetime?.slice(11,16)||'—';
    const pax = c.passagers?.length || c.pax || 1;
    const terms = c.terminaux ? c.terminaux.replace(/CDG/g,'') : '';
    const info = getClientInfo(c.client);
    const dirIcon = getDirectionIcon(c);
    const ligne1 = raccourcirLieu(c.depart||c.lieu) + ' / ' + raccourcirLieu(c.arrivee||c.duree) + (terms?' / '+terms:'');
    // Code facturation : REF / VEHICULE / NUM / CHAUFFEUR — ex: BR / B / 9 / Mustafa
    const codeFact = (c.codeFact||c.ref||'').split('/').filter(x=>x&&x!=='NC').slice(0,3).join(' / ');
    // Libelle vehicule lisible : facilite l'affectation d'un chauffeur au bon
    // type de vehicule sans avoir a ouvrir la course.
    const vehNom = {berline:'Berline',van:'Van',sprinter:'Sprinter',bus:'Bus',pmr:'PMR',limousine:'Limousine',classes:'Classe S'}[c.vehicule]||'Berline';
    // \u2605 D\u00e9tection auto couleur de texte (noir ou blanc) selon la luminosit\u00e9 du fond client.
    const txtColor = texteLisible(color);
    const bgContrast = badgeContraste(color);
    const vehBadge = '<span style="display:inline-block;background:'+bgContrast+';border-radius:5px;padding:2px 8px;font-weight:800;margin-right:6px;font-size:11.5px;color:'+txtColor+';white-space:nowrap">'+vehNom+' \u00b7 '+pax+' pax</span>';
    const codeFactPart = codeFact ? '<span style="opacity:0.85;color:'+txtColor+'">'+E(codeFact)+'</span>' : '';
    return `<div style="position:relative;margin-bottom:8px">
      <input type="checkbox" class="agenda-chk" data-id="${c._id}" onchange="onAgendaChkChange()" onclick="event.stopPropagation()"
        style="position:absolute;left:12px;top:12px;width:28px;height:28px;cursor:pointer;z-index:2;accent-color:${txtColor}">
      <div onclick="viewCourseDetail('${c._id}')" style="background:${color};border-radius:12px;padding:12px 14px 12px 12px;cursor:pointer;color:${txtColor};position:relative;overflow:hidden;min-height:72px;box-shadow:0 2px 6px rgba(0,0,0,0.08)">
        <!-- Ligne 1 : Heure + Depart + Arrivee sur UNE SEULE ligne (ellipsis si trop long).
             Padding-left = 44px pour laisser passer la case a cocher (28px a left:12px),
             +2mm d'espace entre case et heure. Taille 16px gras. -->
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px;padding-left:44px;padding-right:50px;min-width:0;min-height:28px">
          <span style="font-family:'Inter',sans-serif;font-size:16px;font-weight:800;letter-spacing:-0.3px;line-height:1.2;flex-shrink:0;color:${txtColor}">${time}</span>
          <span style="font-size:16px;font-weight:700;line-height:1.2;flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:${txtColor}" title="${E(ligne1)}">${ligne1}</span>
        </div>
        <!-- Ligne 2 : badge vehicule colle a gauche (aligne avec la case blanche) + code facturation -->
        <div style="font-size:12px;opacity:0.95;line-height:1.4;padding-right:40px;color:${txtColor};display:flex;align-items:center;flex-wrap:nowrap;overflow:hidden">
          ${vehBadge}${codeFactPart}
        </div>
        <!-- Ligne 3 : nom du chauffeur (ou À assigner) — aligne a gauche -->
        <div style="font-size:13px;margin-top:3px;padding-right:40px;color:${txtColor};line-height:1.3">
          ${c.chauffeur?'<span style="font-weight:500">👤 '+E(c.chauffeur)+'</span>':'<em style="opacity:0.75;color:'+txtColor+';font-weight:500">À assigner</em>'}
        </div>
        <!-- Boutons empiles VERTICALEMENT (lien + eclair) -->
        <div style="position:absolute;right:8px;top:8px;display:flex;flex-direction:column;gap:4px;align-items:flex-end">
          <button onclick="event.stopPropagation();genererLienExterne('${c._id}')" title="Lien chauffeur externe"
            style="background:${bgContrast};border:none;border-radius:8px;padding:5px 8px;color:${txtColor};font-size:12px;font-weight:700;cursor:pointer;line-height:1">🔗</button>
          ${!c.chauffeur?`<button onclick="event.stopPropagation();autoDispatch('${c._id}')" title="Auto-dispatch"
            style="background:${bgContrast};border:none;border-radius:8px;padding:5px 8px;color:${txtColor};font-size:12px;font-weight:700;cursor:pointer;line-height:1">⚡</button>`:''}
        </div>
      </div>
    </div>`;
   } catch(cardErr) {
    // Une course malformée ne doit pas casser tout l'agenda : carte de secours.
    console.error('Carte course en erreur:', c && c._id, cardErr);
    return `<div onclick="viewCourseDetail('${c&&c._id}')" style="background:#7c2d2d;border-radius:10px;padding:12px 14px;margin-bottom:6px;color:#fff;cursor:pointer">
      <div style="font-size:14px;font-weight:700">⚠️ ${E(raccourcirLieu(c&&(c.depart||c.lieu)))} → ${E(raccourcirLieu(c&&c.arrivee))}</div>
      <div style="font-size:12px;opacity:0.85;margin-top:3px">${E((c&&c.datetime)||'')} · ${E((c&&c.chauffeur)||'À assigner')}</div>
    </div>`;
   }
   })();
  }).join('');
}

// ── Recherche dans le dispatch ──────────────────────────────────────────────
// Sans accents, sans majuscules, ponctuation remplacée par des espaces.
function agendaNormRech(s) {
  return String(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim();
}
// Une course correspond si CHAQUE mot tapé se retrouve dans le chauffeur, le
// client ou un passager (« dup mar » trouve « Marc Dupuis »).
function agendaCourseCorrespond(c, mots) {
  const t = [c.chauffeur, c.extChauffeurNom, c.client, c.passager, c.nomClient, c.createdByClient];
  (c.passagers || []).forEach(function(p){ if (p) t.push(p.prenom, p.nom); });
  if (c.chauffeurId && Array.isArray(D.chauffeurs)) {
    const ch = D.chauffeurs.find(function(x){ return x._id === c.chauffeurId; });
    if (ch) t.push(ch.prenom, ch.nom);
  }
  const txt = ' ' + agendaNormRech(t.filter(function(x){ return typeof x === 'string' && x; }).join(' ')) + ' ';
  return mots.every(function(m){ return txt.indexOf(m) >= 0; });
}
window.agendaRechercheEffacer = function() {
  window.agendaRecherche = '';
  const i = document.getElementById('agenda-search'); if (i) i.value = '';
  const x = document.getElementById('agenda-search-clear'); if (x) x.style.display = 'none';
  try { renderAgenda(); } catch(e){}
};



// ── FICHE DÉTAIL — DESIGN PROPRE EN SECTIONS (comme la vue édition) ──
window.viewCourseDetail = function(id) {
  const c = D.courses.find(x=>x._id===id);
  if(!c) return;
  const color = getClientColor(c.client, c);
  const time = c.datetime?.slice(11,16)||'—';
  const dateStr = c.datetime ? parseLocalDT(c.datetime).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}) : '—';
  const pax = c.passagers?.length || c.pax || 1;
  const info = getClientInfo(c.client);
  const codeFact = c.codeFact || (c.ref||'').split('/').filter(x=>x&&x!=='NC').slice(0,3).join(' / ');
  const vehNom = {berline:'Berline',van:'Van',sprinter:'Sprinter',bus:'Bus',pmr:'PMR',limousine:'Limousine',classes:'Classe S'}[c.vehicule]||'Berline';
  const vehIcon = {berline:'🚗',van:'🚐',sprinter:'🚌',bus:'🚍',pmr:'♿',limousine:'🥂',classes:'🖤'}[c.vehicule]||'🚗';
  const estStaff = SESSION.role!=='chauffeur';

  // Nom passager + téléphone
  const passagerNom = c.passagers?.length
    ? (c.passagers[0].prenom||'') + ' ' + (c.passagers[0].nom||'')
    : (c.passager||'');
  const passagerTel = c.passagers?.[0]?.tel || c.tel || '';

  // Notes — nettoyage : si c'est un bloc LogiPax ("Nb Bagages:... TYPE VEHICULE:..."), on affiche en liste
  let notesHtml = '';
  if(c.notes) {
    const notes = String(c.notes).trim();
    const items = notes.split(/\r?\n/).filter(x=>x.trim());
    if(items.length > 1) {
      notesHtml = items.map(it => '<div style="padding:4px 0;color:#4a4a4a">' + E(it.trim()) + '</div>').join('');
    } else {
      notesHtml = '<div style="color:#4a4a4a">' + E(notes).replace(/\n/g,'<br>') + '</div>';
    }
  }

  // Helpers de section
  const section = (iconOrLabel, titre, contenu) => `
    <div style="margin-top:18px;padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
      <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">${iconOrLabel}${titre?' '+titre:''}</div>
      <div style="font-size:17px;color:#1a1a1a;line-height:1.35">${contenu}</div>
    </div>`;

  const twoCol = (label1, val1, label2, val2) => `
    <div style="margin-top:18px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
      <div style="padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
        <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">${label1}</div>
        <div style="font-size:17px;color:#1a1a1a;line-height:1.3;word-break:break-word">${val1||'—'}</div>
      </div>
      <div style="padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
        <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">${label2}</div>
        <div style="font-size:17px;color:#1a1a1a;line-height:1.3;word-break:break-word">${val2||'—'}</div>
      </div>
    </div>`;

  // Bloc prix (admin/dispatch uniquement)
  // ★ Le prix affiché inclut DÉSORMAIS la majoration nuit/weekend + le supplément
  // d'attente, pour que le staff voit immédiatement le montant TTC total à
  // facturer au client et à verser au chauffeur. Une ventilation est détaillée
  // en dessous quand il y a un supplément.
  let bPrix = '';
  if(estStaff && (c.prix != null || c.prixChauffeur != null)) {
    const baseClient = c.prix != null ? parseFloat(c.prix) : null;
    const baseChauff = c.prixChauffeur != null ? parseFloat(c.prixChauffeur) : null;
    const _w = calcWaitFees(c);
    const _m = getCourseMajoration(c);
    const pctMajo = _m ? _m.pct : 0;

    const majoClient = (baseClient != null && pctMajo > 0) ? Math.round(baseClient * pctMajo) / 100 : 0;
    const majoChauff = (baseChauff != null && pctMajo > 0) ? Math.round(baseChauff * pctMajo) / 100 : 0;
    const attClient = _w ? _w.clientFee : 0;
    const attChauff = _w ? _w.chauffeurFee : 0;

    const totalClient = baseClient != null ? Math.round((baseClient + majoClient + attClient) * 100) / 100 : null;
    const totalChauff = baseChauff != null ? Math.round((baseChauff + majoChauff + attChauff) * 100) / 100 : null;
    const diff = (totalClient != null && totalChauff != null) ? Math.max(0, totalClient - totalChauff).toFixed(2) : null;

    const hasSuppClient = (majoClient + attClient) > 0;
    const hasSuppChauff = (majoChauff + attChauff) > 0;

    const ventilationClient = hasSuppClient ? `
      <div style="font-size:11px;color:#777;margin-top:6px;line-height:1.5">
        Base : ${baseClient.toFixed(2)}€${majoClient>0 ? `<br>+ Majoration ${pctMajo}% : +${majoClient.toFixed(2)}€` : ''}${attClient>0 ? `<br>+ Attente : +${attClient.toFixed(2)}€` : ''}
      </div>` : '';
    const ventilationChauff = hasSuppChauff ? `
      <div style="font-size:11px;color:#777;margin-top:6px;line-height:1.5">
        Base : ${baseChauff.toFixed(2)}€${majoChauff>0 ? `<br>+ Majoration ${pctMajo}% : +${majoChauff.toFixed(2)}€` : ''}${attChauff>0 ? `<br>+ Attente : +${attChauff.toFixed(2)}€` : ''}
      </div>` : '';

    bPrix = `
      <div style="margin-top:18px;display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div style="padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
          <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">💶 Prix client TTC</div>
          <div style="font-size:22px;color:#1a1a1a;font-weight:700">${totalClient!=null?totalClient.toFixed(2)+'€':'—'}</div>
          ${ventilationClient}
        </div>
        <div style="padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
          <div style="font-size:11px;font-weight:700;color:#16a34a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">🚗 Prix chauffeur</div>
          <div style="font-size:22px;color:#16a34a;font-weight:700">${totalChauff!=null?totalChauff.toFixed(2)+'€':'—'}</div>
          ${ventilationChauff}
        </div>
      </div>
      ${diff!=null?`<div style="margin-top:10px;padding:12px 16px;background:rgba(217,119,6,0.08);border:1px solid rgba(217,119,6,0.3);border-radius:14px;display:flex;justify-content:space-between;align-items:center">
        <div style="font-size:13px;font-weight:700;color:#b45309">Différence (commission)</div>
        <div style="font-size:18px;font-weight:700;color:#b45309">${diff}€</div>
      </div>`:''}`;
  }

  // Bloc attente
  let bAttente = '';
  const w = calcWaitFees(c);
  if(w) {
    const hasChf = w.chauffeurFee > 0;
    const hasCl = w.clientFee > 0;
    bAttente = `
      <div style="margin-top:18px;padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
        <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:8px">⏱️ Temps d'attente</div>
        <div style="font-size:17px;color:#1a1a1a;font-weight:700;margin-bottom:6px">${fmtWaitDuration(w.waitMin)}</div>
        ${estStaff?`
          <div style="font-size:13px;color:${hasCl?'#d97706':'#666'};margin-top:4px">${hasCl?`💰 Supplément client : +${w.clientFee}€`:`✓ Dans le forfait client`}</div>
          <div style="font-size:13px;color:${hasChf?'#0891b2':'#666'};margin-top:4px">${hasChf?`🚗 À payer chauffeur : +${w.chauffeurFee}€`:`✓ Dans le forfait chauffeur`}</div>
        `:`<div style="font-size:13px;color:${hasChf?'#0891b2':'#666'};margin-top:4px">${hasChf?`Supplément attente : +${w.chauffeurFee}€`:`${w.chauffeurFreeMin} min incluses`}</div>`}
      </div>`;
  }

  // Bloc vol avec lien
  let bVol = '';
  if(c.vol) {
    bVol = `
      <div style="margin-top:18px;padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
        <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">✈️ Vol</div>
        <div style="font-size:17px;color:#1a1a1a;font-weight:700">${E(c.vol)}</div>
        <a href="https://www.flightradar24.com/data/flights/${encodeURIComponent(c.vol.replace(/\s+/g,'').toLowerCase())}" target="_blank" style="display:inline-block;margin-top:10px;background:#0891b2;border-radius:10px;padding:9px 14px;font-size:13px;color:#fff;font-weight:600;text-decoration:none">Suivre en direct →</a>
      </div>`;
  }

  // Bloc options
  let bOptions = '';
  if(c.options && c.options.length) {
    bOptions = `
      <div style="margin-top:18px;padding:14px 16px;background:rgba(217,119,6,0.06);border:1px solid rgba(217,119,6,0.25);border-radius:14px">
        <div style="font-size:11px;font-weight:700;color:#b45309;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:6px">⭐ Options</div>
        <div style="font-size:16px;color:#b45309;font-weight:600">${c.options.map(E).join(' · ')}</div>
      </div>`;
  }

  const ov = document.createElement('div');
  ov.id = 'course-detail-ov';
  ov.style.cssText = 'position:fixed;inset:0;background:#fff;z-index:600;display:flex;flex-direction:column;overflow:hidden';
  ov.innerHTML = `
    <!-- Barre haut -->
    <div style="display:flex;align-items:center;justify-content:space-between;padding:calc(14px + env(safe-area-inset-top, 0px)) 18px 10px;border-bottom:1px solid #f0f0f0">
      <button onclick="document.getElementById('course-detail-ov').remove()" style="background:none;border:none;font-size:26px;cursor:pointer;color:#333;padding:6px">✕</button>
      <div style="display:flex;align-items:center;gap:14px">
        <button onclick="editCourseGoogle('${c._id}')" title="Modifier" style="background:none;border:none;font-size:24px;cursor:pointer;color:#333;padding:6px">✏️</button>
        <div style="position:relative">
          <button onclick="document.getElementById('cd-menu').style.display=document.getElementById('cd-menu').style.display==='block'?'none':'block'" style="background:none;border:none;font-size:28px;cursor:pointer;color:#333;padding:6px">⋯</button>
          <div id="cd-menu" style="display:none;position:absolute;right:0;top:36px;background:#fff;border-radius:12px;box-shadow:0 8px 30px rgba(0,0,0,0.18);overflow:hidden;min-width:200px;z-index:10;border:1px solid #e8e8e8">
            <button onclick="duplicateCourse('${c._id}')" style="display:flex;align-items:center;justify-content:space-between;width:100%;background:none;border:none;border-bottom:1px solid #f0f0f0;padding:14px 18px;font-size:15px;color:#222;cursor:pointer;text-align:left">Dupliquer <span>📋</span></button>
            ${(parseFloat(c.prix)>0 && !stripeCoursePayee(c)) ? `<button onclick="document.getElementById('course-detail-ov').remove();payLienCourse('${c._id}')" style="display:flex;align-items:center;justify-content:space-between;width:100%;background:none;border:none;border-bottom:1px solid #f0f0f0;padding:14px 18px;font-size:15px;color:#222;cursor:pointer;text-align:left">Lien de paiement <span>💳</span></button>` : ''}
            <button onclick="document.getElementById('course-detail-ov').remove();delCourse('${c._id}')" style="display:flex;align-items:center;justify-content:space-between;width:100%;background:none;border:none;padding:14px 18px;font-size:15px;color:#d93025;cursor:pointer;text-align:left">Supprimer <span>🗑️</span></button>
          </div>
        </div>
      </div>
    </div>

    <!-- Contenu scrollable -->
    <div style="flex:1;overflow-y:auto;padding:18px 18px 60px">
      <!-- Bandeau client coloré -->
      <div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:${color};border-radius:14px;color:#fff;margin-bottom:8px">
        <div style="width:38px;height:38px;border-radius:10px;background:rgba(255,255,255,0.25);display:flex;align-items:center;justify-content:center;font-size:20px;font-weight:800">${(c.client||'?').slice(0,1).toUpperCase()}</div>
        <div style="flex:1;min-width:0">
          <div style="font-size:16px;font-weight:700;line-height:1.2;word-break:break-word">${E(info.label||c.client||'—')}</div>
          <div style="font-size:12px;opacity:0.92;margin-top:2px">${sBdg(c.statut)}</div>
        </div>
      </div>

      <!-- Départ -->
      ${section('📍', 'DÉPART', E(c.depart||c.lieu||'—'))}
      <!-- Arrivée -->
      ${section('🏁', 'ARRIVÉE', E(c.arrivee||c.duree||'—'))}
      <!-- Date / Heure -->
      ${section('🕐', 'DATE & HEURE', dateStr + ' <strong style="color:#000">' + time + '</strong>')}

      <!-- Code facturation si présent -->
      ${codeFact?section('🔖', 'CODE FACTURATION', E(codeFact)):''}

      <!-- Chauffeur -->
      ${section('👤', 'CHAUFFEUR', c.chauffeur?E(c.chauffeur)+(c.chauffeurTel?' · <a href="tel:'+String(c.chauffeurTel).replace(/\s/g,'')+'" style="color:#1a73e8;text-decoration:none">'+E(c.chauffeurTel)+'</a>':''):'<em style="color:#999">À assigner</em>')}

      <!-- Client / Téléphone -->
      ${twoCol('👤 CLIENT', E(c.client||'—'), '📞 TÉLÉPHONE', c.tel?'<a href="tel:'+String(c.tel).replace(/\s/g,'')+'" style="color:#1a73e8;text-decoration:none">'+E(c.tel)+'</a>':'—')}

      <!-- Passagers : liste complete avec ✅ present / ❌ absent -->
      ${(c.passagers && c.passagers.length)
        ? section('🧳', 'PASSAGERS', c.passagers.map((p,i) => {
            const isPresent = p.present !== false;
            const nom = ((p.prenom||'')+' '+(p.nom||'')).trim() || ('Passager '+(i+1));
            const telLink = p.tel ? ' · <a href="tel:'+String(p.tel).replace(/\s/g,'')+'" style="color:#1a73e8;text-decoration:none;font-size:15px">'+E(p.tel)+'</a>' : '';
            return '<div style="display:flex;align-items:center;gap:10px;padding:6px 0'+(i<c.passagers.length-1?';border-bottom:1px solid #eee':'')+'">'
              + '<span style="font-size:20px;flex-shrink:0">'+(isPresent?'✅':'❌')+'</span>'
              + '<span style="flex:1;min-width:0"><strong style="color:'+(isPresent?'#1a1a1a':'#999')+(isPresent?'':';text-decoration:line-through')+'">'+E(nom)+'</strong>'+telLink+'</span>'
              + '</div>';
          }).join(''))
        : (passagerNom.trim()?section('🧳', 'PASSAGER', '<strong>'+E(passagerNom.trim())+'</strong>'+(passagerTel?' · <a href="tel:'+String(passagerTel).replace(/\s/g,'')+'" style="color:#1a73e8;text-decoration:none">'+E(passagerTel)+'</a>':'')):'')}

      <!-- Véhicule + Pax -->
      ${twoCol(vehIcon+' VÉHICULE', E(vehNom), '👥 PASSAGERS', pax+' pax'+(c.bags||c.bagages?' · 🧳 '+(c.bags||c.bagages):''))}

      <!-- Options -->
      ${bOptions}

      <!-- Vol -->
      ${bVol}

      <!-- Prix (staff seulement) -->
      ${bPrix}

      <!-- Mode de paiement -->
      ${estStaff && c.payMode?section('💳', 'MODE DE PAIEMENT', c.payMode==='direct'?'Direct chauffeur':c.payMode==='mobilea'?'MOBILEA':E(c.payMode)):''}

      <!-- Temps d'attente -->
      ${bAttente}

      <!-- Notes -->
      ${notesHtml?`<div style="margin-top:18px;padding:14px 16px;background:#fafafa;border-radius:14px;border:1px solid #ececec">
        <div style="font-size:11px;font-weight:700;color:#8a8a8a;letter-spacing:0.5px;text-transform:uppercase;margin-bottom:8px">📝 NOTES</div>
        <div style="font-size:14px">${notesHtml}</div>
      </div>`:''}

      <!-- Voir tous les transferts du client -->
      <div onclick="document.getElementById('course-detail-ov').remove();viewClientCourses('${JA(c.client||'')}')"
        style="margin-top:18px;padding:14px 16px;background:#f0f7ff;border:1px solid #cfe3ff;border-radius:14px;cursor:pointer;display:flex;align-items:center;justify-content:space-between">
        <div>
          <div style="font-size:11px;font-weight:700;color:#1a73e8;letter-spacing:0.5px;text-transform:uppercase">📅 Historique client</div>
          <div style="font-size:14px;color:#1a73e8;margin-top:4px">Voir tous les transferts de ${E(c.client||'ce client')}</div>
        </div>
        <div style="font-size:18px;color:#1a73e8">→</div>
      </div>
    </div>`;
  document.body.appendChild(ov);
};

// ── ÉDITION RAPIDE STYLE GOOGLE AGENDA ──
// Helpers de l'écran d'édition de course (prix + paiement)
window.geMajDiff = function() {
  const pc = parseFloat(document.getElementById('ge-prix')?.value)||0;
  const pch = parseFloat(document.getElementById('ge-prix-chauffeur')?.value)||0;
  const el = document.getElementById('ge-diff');
  if(el) el.textContent = (pc && pch) ? Math.max(0, pc-pch).toFixed(2)+'€' : '—';
};
window.geSetPay = function(mode) {
  document.getElementById('ge-pay-mode').value = mode;
  const m = document.getElementById('ge-pay-mobilea');
  const d = document.getElementById('ge-pay-direct');
  if(mode==='direct') {
    m.style.cssText='flex:1;padding:12px;border-radius:10px;text-align:center;cursor:pointer;border:2px solid #e0e3e8;background:#fff;font-weight:700;font-size:13px;color:#999';
    d.style.cssText='flex:1;padding:12px;border-radius:10px;text-align:center;cursor:pointer;border:2px solid #d97706;background:rgba(217,119,6,0.1);font-weight:700;font-size:13px;color:#d97706';
  } else {
    m.style.cssText='flex:1;padding:12px;border-radius:10px;text-align:center;cursor:pointer;border:2px solid #b8860b;background:rgba(184,134,11,0.1);font-weight:700;font-size:13px;color:#b8860b';
    d.style.cssText='flex:1;padding:12px;border-radius:10px;text-align:center;cursor:pointer;border:2px solid #e0e3e8;background:#fff;font-weight:700;font-size:13px;color:#999';
  }
};

window.editCourseGoogle = function(id) {
  const c = D.courses.find(x=>x._id===id);
  if(!c) return;
  const old = document.getElementById('course-detail-ov');
  if(old) old.remove();
  const color = getClientColor(c.client, c);
  const codeFact = c.codeFact || (c.ref||'').split('/').filter(x=>x&&x!=='NC').slice(0,3).join(' / ');
  const dt = c.datetime || '';
  const chauffeursOptions = D.chauffeurs.map(ch=>{
    const n = ch.prenom+(ch.nom?' '+ch.nom:'');
    return '<option value="'+n+'">';
  }).join('');

  const ov = document.createElement('div');
  ov.id = 'course-edit-ov';
  ov.style.cssText = 'position:fixed;inset:0;background:#fff;z-index:650;display:flex;flex-direction:column;overflow:hidden';
  ov.innerHTML = `
    <!-- Barre haut : Annuler / OK -->
    <div style="display:flex;align-items:center;justify-content:space-between;padding:calc(16px + env(safe-area-inset-top, 0px)) 20px 16px;border-bottom:1px solid #f0f0f0">
      <button onclick="document.getElementById('course-edit-ov').remove()" style="background:none;border:none;font-size:20px;color:#1a73e8;cursor:pointer;font-weight:500">Annuler</button>
      <button onclick="saveCourseGoogle('${c._id}')" style="background:none;border:none;font-size:20px;color:#1a73e8;cursor:pointer;font-weight:700">OK</button>
    </div>

    <div style="flex:1;overflow-y:auto;padding:10px 24px 40px">
      <!-- Titre : Départ / Arrivée -->
      <!-- Départ et Arrivée séparés pour pouvoir modifier chacun indépendamment -->
      <div style="padding:14px 0;border-bottom:1px solid #f0f0f0">
        <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">📍 Départ</label>
        <input type="text" id="ge-depart" value="${(c.depart||c.lieu||'').replace(/"/g,'&quot;')}"
          placeholder="Adresse de départ"
          style="width:100%;border:none;outline:none;font-size:20px;font-weight:500;color:#1a1a1a;padding:4px 0" maxlength="200">
      </div>
      <div style="padding:14px 0;border-bottom:1px solid #f0f0f0">
        <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">🏁 Arrivée</label>
        <input type="text" id="ge-arrivee" value="${(c.arrivee||'').replace(/"/g,'&quot;')}"
          placeholder="Adresse d'arrivée"
          style="width:100%;border:none;outline:none;font-size:20px;font-weight:500;color:#1a1a1a;padding:4px 0" maxlength="200">
      </div>

      <!-- Date et heure -->
      <div style="display:flex;align-items:center;gap:16px;padding:18px 0;border-bottom:1px solid #f0f0f0">
        <span style="font-size:22px;color:#5f6368">🕐</span>
        <input type="datetime-local" id="ge-datetime" value="${dt}"
          style="flex:1;border:none;outline:none;font-size:30px;color:#222;line-height:1.3;background:none">
      </div>

      <!-- Code facturation : BR / B / 9 -->
      <div style="display:flex;align-items:center;gap:16px;padding:18px 0;border-bottom:1px solid #f0f0f0">
        <span style="font-size:22px;color:#5f6368">📍</span>
        <input type="text" id="ge-code" value="${codeFact.replace(/"/g,'&quot;')}"
          placeholder="BR / B / 9"
          style="flex:1;border:none;outline:none;font-size:30px;color:#222;line-height:1.3" maxlength="200">
      </div>

      <!-- Chauffeur avec recherche -->
      <div style="padding:18px 0;border-bottom:1px solid #f0f0f0">
        <div style="display:flex;align-items:center;gap:16px">
          <span style="font-size:22px;color:#5f6368">👤</span>
          <input type="text" id="ge-chauffeur" value="${(c.chauffeur||'').replace(/"/g,'&quot;')}"
            placeholder="Rechercher un chauffeur..."
            oninput="geSearchChauffeur(this.value)"
            onfocus="geSearchChauffeur(this.value)"
            style="flex:1;border:none;outline:none;font-size:30px;color:#222;line-height:1.3;background:none" maxlength="200">
        </div>
        <div id="ge-ch-results" style="display:none;margin-top:10px;background:#f8f9fa;border-radius:14px;overflow:hidden;max-height:320px;overflow-y:auto"></div>
      </div>

      <!-- Client + Téléphone -->
      <div style="display:flex;gap:16px;padding:18px 0;border-bottom:1px solid #f0f0f0">
        <div style="flex:1">
          <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">👤 Client</label>
          <input type="text" id="ge-client" value="${(c.client||'').replace(/"/g,'&quot;')}" placeholder="Nom du client"
            style="width:100%;border:none;outline:none;font-size:18px;color:#1a1a1a;padding:4px 0" maxlength="200">
        </div>
        <div style="flex:1">
          <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">📞 Téléphone</label>
          <input type="tel" id="ge-tel" value="${(c.tel||'').replace(/"/g,'&quot;')}" placeholder="+33 6 ..."
            style="width:100%;border:none;outline:none;font-size:18px;color:#1a1a1a;padding:4px 0" maxlength="30">
        </div>
      </div>

      <!-- Véhicule -->
      <div style="padding:18px 0;border-bottom:1px solid #f0f0f0">
        <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">🚗 Véhicule</label>
        <select id="ge-vehicule" style="width:100%;border:none;outline:none;font-size:18px;color:#1a1a1a;padding:4px 0;background:transparent">
          ${['berline','van','sprinter','bus','pmr','limousine','classes'].map(v=>{
            const lbl={berline:'🚗 Berline',van:'🚐 Van',sprinter:'🚌 Sprinter',bus:'🚍 Bus',pmr:'♿ Van PMR',limousine:'🥂 Limousine',classes:'🖤 Classe S'}[v];
            return '<option value="'+v+'"'+(c.vehicule===v?' selected':'')+'>'+lbl+'</option>';
          }).join('')}
        </select>
      </div>

      <!-- Prix client + Prix chauffeur -->
      <div style="display:flex;gap:16px;padding:18px 0;border-bottom:1px solid #f0f0f0">
        <div style="flex:1">
          <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">💶 Prix client (€)</label>
          <input type="number" id="ge-prix" value="${c.prix!=null?c.prix:''}" placeholder="0" oninput="geMajDiff()"
            style="width:100%;border:none;outline:none;font-size:18px;color:#1a1a1a;padding:4px 0" step="0.01">
        </div>
        <div style="flex:1">
          <label style="display:block;font-size:11px;color:#16a34a;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:4px">🚗 Prix chauffeur (€)</label>
          <input type="number" id="ge-prix-chauffeur" value="${c.prixChauffeur!=null?c.prixChauffeur:''}" placeholder="0" oninput="geMajDiff()"
            style="width:100%;border:none;outline:none;font-size:18px;color:#16a34a;font-weight:600;padding:4px 0" step="0.01">
        </div>
      </div>
      <!-- Différence calculée -->
      <div style="display:flex;align-items:center;justify-content:space-between;padding:12px 0;border-bottom:1px solid #f0f0f0">
        <span style="font-size:13px;color:#d97706;font-weight:600">Différence (commission)</span>
        <span id="ge-diff" style="font-size:18px;font-weight:800;color:#d97706">—</span>
      </div>

      <!-- Mode de paiement -->
      <div style="padding:18px 0;border-bottom:1px solid #f0f0f0">
        <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:8px">💳 Mode de paiement</label>
        <div style="display:flex;gap:10px">
          <div id="ge-pay-mobilea" onclick="geSetPay('mobilea')" style="flex:1;padding:12px;border-radius:10px;text-align:center;cursor:pointer;border:2px solid ${c.payMode!=='direct'?'#b8860b':'#e0e3e8'};background:${c.payMode!=='direct'?'rgba(184,134,11,0.1)':'#fff'};font-weight:700;font-size:13px;color:${c.payMode!=='direct'?'#b8860b':'#999'}">🏢 En compte</div>
          <div id="ge-pay-direct" onclick="geSetPay('direct')" style="flex:1;padding:12px;border-radius:10px;text-align:center;cursor:pointer;border:2px solid ${c.payMode==='direct'?'#d97706':'#e0e3e8'};background:${c.payMode==='direct'?'rgba(217,119,6,0.1)':'#fff'};font-weight:700;font-size:13px;color:${c.payMode==='direct'?'#d97706':'#999'}">🚗 Paiement à bord</div>
        </div>
        <input type="hidden" id="ge-pay-mode" value="${c.payMode==='direct'?'direct':'mobilea'}">
      </div>

      <!-- Proposer aux chauffeurs (prioritaires d'abord, puis à tous) -->
      <div style="padding:16px 0;border-bottom:1px solid #f0f0f0;display:flex;flex-direction:column;gap:10px">
        <button type="button" onclick="proposerAuxPrioritaires('${c._id}')" style="display:flex;align-items:center;justify-content:center;gap:8px;width:100%;background:linear-gradient(135deg,#fef3c7,#fde68a);border:2px solid #d97706;border-radius:12px;padding:13px;color:#92400e;font-size:14px;font-weight:800;cursor:pointer">
          ⭐ Proposer aux prioritaires
        </button>
        <div style="font-size:11px;color:#999;margin-top:-4px;text-align:center">Réservé aux chauffeurs ⭐ — ne s'ouvre pas aux autres. Idéal pour envoyer à l'avance.</div>
        <button type="button" onclick="ouvrirCourseATous('${c._id}')" style="display:flex;align-items:center;justify-content:center;gap:8px;width:100%;background:linear-gradient(135deg,#fffbeb,#fef3c7);border:2px solid #f59e0b;border-radius:12px;padding:13px;color:#b45309;font-size:14px;font-weight:800;cursor:pointer">
          🙋 Proposer à tous les chauffeurs
        </button>
        <div style="font-size:11px;color:#999;margin-top:-4px;text-align:center">Le premier chauffeur qui accepte garde le transfert</div>
      </div>

      <!-- Liste visuelle des passagers avec ✅/❌ (cliquer pour basculer present/absent) -->
      ${(c.passagers && c.passagers.length) ? `
      <div style="padding:14px 0;border-bottom:1px solid #f0f0f0">
        <label style="display:block;font-size:11px;color:#5f6368;font-weight:600;text-transform:uppercase;letter-spacing:0.5px;margin-bottom:10px">🧳 PASSAGERS (appuyer sur ✅/❌ pour basculer)</label>
        <div id="ge-pax-presence-list">
          ${c.passagers.map((p, i) => {
            const isPresent = p.present !== false;
            const nom = ((p.prenom||'')+' '+(p.nom||'')).trim() || ('Passager '+(i+1));
            return `<div onclick="geTogglePaxPresence('${c._id}',${i})" style="display:flex;align-items:center;gap:12px;padding:10px 4px;cursor:pointer;border-bottom:1px solid #f5f5f5">
              <span style="font-size:24px;flex-shrink:0;line-height:1">${isPresent?'✅':'❌'}</span>
              <div style="flex:1;min-width:0">
                <div style="font-size:17px;font-weight:600;color:${isPresent?'#1a1a1a':'#999'};${isPresent?'':'text-decoration:line-through'}">${E(nom)}</div>
                ${p.tel?`<div style="font-size:13px;color:#888">${E(p.tel)}</div>`:''}
              </div>
            </div>`;
          }).join('')}
        </div>
      </div>` : ''}

      <div style="display:flex;align-items:flex-start;gap:16px;padding:18px 0;border-bottom:1px solid #f0f0f0">
        <span style="font-size:22px;color:#5f6368;margin-top:4px">≡</span>
        <textarea id="ge-pax" rows="6"
          placeholder="07:20 / TO3910 / 3 / R4N7XF3F5KF / Angela Bruciafreddo Italy +393491972346"
          style="flex:1;border:none;outline:none;font-size:20px;color:#222;resize:vertical;line-height:1.6;font-family:inherit" maxlength="2000">${(c.passagers||[]).map(p=>[p.harrivee||'',p.vol||'',p.terminal||'',p.refClient||'',((p.prenom||'')+' '+(p.nom||'')).trim()+(p.tel?' '+p.tel:'')].join(' / ')).join('\n')}</textarea>
      </div>

      <!-- Notes -->
      <div style="display:flex;align-items:flex-start;gap:16px;padding:18px 0">
        <span style="font-size:22px;color:#5f6368;margin-top:4px">📝</span>
        <textarea id="ge-notes" rows="3" placeholder="Notes..."
          style="flex:1;border:none;outline:none;font-size:20px;color:#222;resize:vertical;font-family:inherit" maxlength="2000">${E(c.notes||'')}</textarea>
      </div>
    </div>`;
  document.body.appendChild(ov);
  try { geMajDiff(); } catch(e){}
};

window.geSearchChauffeur = function(query) {
  const box = document.getElementById('ge-ch-results');
  if(!box) return;
  const q = (query||'').toLowerCase().trim();
  const matches = D.chauffeurs.filter(ch => {
    const n = (ch.prenom+' '+(ch.nom||'')).toLowerCase();
    return !q || n.includes(q);
  }).slice(0, 8);

  if(!matches.length) { box.style.display='none'; return; }

  box.style.display = 'block';
  box.innerHTML = matches.map(ch => {
    const name = ch.prenom+(ch.nom?' '+ch.nom:'');
    const vehIco = {berline:'🚗',van:'🚐',sprinter:'🚌',bus:'🚍',pmr:'♿',limousine:'🥂',classes:'🖤'}[ch.vehicule]||'🚗';
    const dispo = ch.statut !== 'indisponible';
    const av = name.split(' ').map(n=>n[0]||'').join('').slice(0,2).toUpperCase();
    return '<div onclick="geSelectChauffeur(\''+name.replace(/'/g,"\\'")+'\')" '
      + 'style="display:flex;align-items:center;gap:14px;padding:14px 18px;cursor:pointer;border-bottom:1px solid #eee" '
      + 'onmouseover="this.style.background=\'#eef\'" onmouseout="this.style.background=\'none\'">'
      + '<div style="width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#b8860b,#d4a017);display:flex;align-items:center;justify-content:center;font-weight:800;font-size:16px;color:#fff;flex-shrink:0">'+av+'</div>'
      + '<div style="flex:1"><div style="font-size:22px;font-weight:600;color:#111">'+name+'</div>'
      + '<div style="font-size:16px;color:#777">'+vehIco+' '+(ch.vehicule||'berline')+'</div></div>'
      + (dispo?'<span style="background:#dcfce7;color:#166534;font-size:14px;font-weight:700;padding:4px 12px;border-radius:20px">✓ Dispo</span>':'<span style="background:#fee;color:#c00;font-size:14px;font-weight:700;padding:4px 12px;border-radius:20px">✗ Indispo</span>')
      + '</div>';
  }).join('');
};

window.geSelectChauffeur = function(name) {
  const inp = document.getElementById('ge-chauffeur');
  if(inp) inp.value = name;
  const box = document.getElementById('ge-ch-results');
  if(box) box.style.display = 'none';
};

// Bascule present/absent pour un passager dans l'editeur "Modifier" rapide.
// Met a jour Firebase immediatement + rafraichit la liste visuelle sans
// fermer la modale. L'etat present/absent est aussi stocke dans
// window._gePresenceOverride pour etre preserve au moment du Save.
window.geTogglePaxPresence = async function(courseId, paxIndex) {
  const c = D.courses.find(x => x._id === courseId);
  if(!c || !c.passagers || !c.passagers[paxIndex]) return;
  const current = c.passagers[paxIndex].present !== false;
  const newPresent = !current;
  // Met a jour la memoire locale tout de suite
  c.passagers[paxIndex] = { ...c.passagers[paxIndex], present: newPresent };
  // Memorise pour que le Save preserve cette valeur
  if(!window._gePresenceOverride) window._gePresenceOverride = {};
  if(!window._gePresenceOverride[courseId]) window._gePresenceOverride[courseId] = {};
  window._gePresenceOverride[courseId][paxIndex] = newPresent;
  // Rafraichit la liste visuelle seule
  const list = document.getElementById('ge-pax-presence-list');
  if(list) {
    list.innerHTML = c.passagers.map((p, i) => {
      const isPresent = p.present !== false;
      const nom = ((p.prenom||'')+' '+(p.nom||'')).trim() || ('Passager '+(i+1));
      return '<div onclick="geTogglePaxPresence(\''+courseId+'\','+i+')" style="display:flex;align-items:center;gap:12px;padding:10px 4px;cursor:pointer;border-bottom:1px solid #f5f5f5">'
        + '<span style="font-size:24px;flex-shrink:0;line-height:1">'+(isPresent?'✅':'❌')+'</span>'
        + '<div style="flex:1;min-width:0">'
        +   '<div style="font-size:17px;font-weight:600;color:'+(isPresent?'#1a1a1a':'#999')+';'+(isPresent?'':'text-decoration:line-through')+'">'+E(nom)+'</div>'
        +   (p.tel?'<div style="font-size:13px;color:#888">'+E(p.tel)+'</div>':'')
        + '</div>'
        + '</div>';
    }).join('');
  }
  // Ecrit en Firebase pour que le changement soit visible ailleurs
  try {
    await fbUpdate('courses', courseId, { passagers: c.passagers, updatedAt: new Date().toISOString() });
  } catch(e){ console.warn('geTogglePaxPresence fbUpdate:', e); }
};

window.saveCourseGoogle = async function(id) {
  // Départ et Arrivée lus depuis leurs champs séparés (plus de découpage de titre)
  const depart = (document.getElementById('ge-depart')?.value||'').trim();
  const arrivee = (document.getElementById('ge-arrivee')?.value||'').trim();
  const datetime = document.getElementById('ge-datetime').value;
  const code = document.getElementById('ge-code').value.trim();
  const chauffeur = document.getElementById('ge-chauffeur').value.trim();
  const client = (document.getElementById('ge-client')?.value||'').trim();
  const tel = (document.getElementById('ge-tel')?.value||'').trim();
  const vehicule = document.getElementById('ge-vehicule')?.value || 'berline';
  let prix = document.getElementById('ge-prix')?.value!=='' ? parseFloat(document.getElementById('ge-prix').value) : null;
  let prixChauffeur = document.getElementById('ge-prix-chauffeur')?.value!=='' ? parseFloat(document.getElementById('ge-prix-chauffeur').value) : null;
  const payMode = document.getElementById('ge-pay-mode')?.value || 'mobilea';
  let marge = (prix!=null && prixChauffeur!=null) ? Math.max(0, prix-prixChauffeur) : null;
  const paxText = document.getElementById('ge-pax').value.trim();
  const notes = document.getElementById('ge-notes').value.trim();

  // Avant de re-parser le textarea, recupere l'etat present/absent actuel +
  // les overrides faits via les clics ✅/❌ dans la modale
  const _coursAvant = (D.courses||[]).find(x => x._id === id);
  const _presenceAvant = (_coursAvant && _coursAvant.passagers) ? _coursAvant.passagers.map(p => p.present !== false) : [];
  const _overrideMap = (window._gePresenceOverride && window._gePresenceOverride[id]) || {};

  // Parser les passagers — parser INTELLIGENT qui detecte si la 1ere colonne
  // est une heure (HH:MM/HHhMM/empty = format 5-col) ou directement le vol
  // (format 4-col LogiPax sans heure). CAS IMPORTANT : si p[0] est vide,
  // c'est le format 5 colonnes avec heure vide — NE PAS decaler.
  const _isHeure = (s) => /^\d{1,2}[:h.]\d{2}$/.test((s||'').trim());
  const passagers = paxText ? paxText.split('\n').filter(l=>l.trim()).map((line, idx)=>{
    const p=line.split('/').map(s=>s.trim());
    // Format 5 colonnes si : p[0] est une heure OU p[0] est vide (heure absente
    // mais slot present). Format 4 colonnes uniquement si p[0] est NON vide
    // et NON heure (ex: "EZY3034").
    const avecHeure = (p[0] === '') || _isHeure(p[0]);
    // Ligne SANS aucun « / » (texte libre) : c'est un nom, pas un n° de vol.
    // Les autres champs resteront ceux d'avant (protection anti-perte).
    const texteLibre = (p.length === 1);
    const harrivee  = texteLibre ? '' : (avecHeure ? (p[0]||'') : '');
    const vol       = texteLibre ? '' : (avecHeure ? (p[1]||'') : (p[0]||''));
    const terminal  = texteLibre ? '' : (avecHeure ? (p[2]||'') : (p[1]||''));
    const refClient = texteLibre ? '' : (avecHeure ? (p[3]||'') : (p[2]||''));
    // Nom+tel : on recupere TOUT ce qui reste a partir de nomTelStart, meme
    // si l'utilisateur a mis des "/" en trop dans le nom. On recombine avec
    // ' / ' pour ne RIEN perdre, puis on extrait le telephone a la fin.
    // Ex: "Dupont / Jr +33612345678" reste intact au lieu de perdre " Jr".
    const nomTelStart = texteLibre ? 0 : (avecHeure ? 4 : 3);
    const nomTelCombine = p.slice(nomTelStart).join(' / ').trim();
    const lastPart = (p[p.length-1]||'').trim();
    const lastPartCleaned = lastPart.replace(/[\s\-\(\)\.]/g,'');
    let tel='', nomComplet='';
    // Cas 1 : le DERNIER champ est purement un telephone → tel = dernier champ,
    //          nom = tout ce qui precede (recombine avec ' / ')
    if(p.length > nomTelStart + 1 && /^[\+\d]{7,15}$/.test(lastPartCleaned)) {
      tel = lastPart;
      nomComplet = p.slice(nomTelStart, p.length - 1).join(' / ').trim();
    } else {
      // Cas 2 : chercher un numero de tel a la fin du texte combine
      const m = nomTelCombine.match(/(\+[\d\s\-\.]{7,18}|\b[\d]{8,15})$/);
      if(m){
        tel = m[1].trim();
        nomComplet = nomTelCombine.slice(0, nomTelCombine.lastIndexOf(m[1])).trim();
      } else {
        // Cas 3 : numéro au milieu du texte (du texte a été ajouté après) →
        // on le sort quand même du nom.
        const tous = nomTelCombine.match(/(\+[\d][\d\s\-\.]{6,17}\d|\b\d{8,15}\b)/g);
        if(tous && tous.length){
          tel = tous[tous.length-1].trim();
          nomComplet = nomTelCombine.replace(tous[tous.length-1], ' ').replace(/\s+/g,' ').trim();
        } else {
          nomComplet = nomTelCombine;
        }
      }
    }
    const pays=['Italy','France','Germany','Spain','UK','USA','Belgium','Netherlands','Switzerland','Portugal','Sweden','Norway','Denmark','Finland','Austria','Poland','Brazil','Ireland','Australia','Canada'];
    const words=nomComplet.split(/\s+/);
    if(words.length>1&&pays.some(x=>x.toLowerCase()===words[words.length-1].toLowerCase())){
      nomComplet=words.slice(0,-1).join(' ');
    }
    const parts=nomComplet.split(/\s+/);
    // Preserve present/absent : override (clic dans modale) > etat avant > true
    let present = true;
    if(_overrideMap[idx] !== undefined) present = _overrideMap[idx];
    else if(_presenceAvant[idx] !== undefined) present = _presenceAvant[idx];

    // ★ PROTECTION ANTI-PERTE : si un champ parse est vide MAIS que l'original
    // avait une valeur, on garde l'original. L'utilisateur peut taper n'importe
    // quoi dans la zone sans risquer de perdre les donnees pre-existantes.
    const _paxAvant = (_coursAvant && _coursAvant.passagers) ? _coursAvant.passagers[idx] : null;
    const _prenom = parts[0] || '';
    const _nom = parts.slice(1).join(' ');
    const _keep = (nouvelleVal, ancienneVal) => (String(nouvelleVal||'').trim() || String(ancienneVal||'').trim() || '');
    return{
      harrivee:  _keep(harrivee,   _paxAvant?.harrivee),
      vol:       _keep(vol,        _paxAvant?.vol),
      terminal:  _keep(terminal,   _paxAvant?.terminal),
      refClient: _keep(refClient,  _paxAvant?.refClient),
      prenom:    _keep(_prenom,    _paxAvant?.prenom),
      nom:       _keep(_nom,       _paxAvant?.nom),
      tel:       _keep(tel,        _paxAvant?.tel),
      present
    };
  }) : [];
  // Nettoie les overrides pour cette course (modif terminee)
  if(window._gePresenceOverride && window._gePresenceOverride[id]) delete window._gePresenceOverride[id];

  const avant = (D.courses||[]).find(x => x._id === id) || null;
  // Recomputer le champ agrege c.terminaux a partir des terminaux de chaque
  // passager, sinon les vues qui affichent c.terminaux (tableau dispatch,
  // carte agenda, liste client) restent coincees sur l'ancienne valeur
  // apres edition (ex: 2F -> 2E). Deduplique et joint par '-'.
  const terminauxAgg = [...new Set(passagers.map(p => (p.terminal||'').trim()).filter(Boolean))].join('-');

  // RECALCUL AUTOMATIQUE DU PRIX quand le nombre de terminaux change
  // (ex: ajout d'un passager avec terminal different apres import LogiPax).
  // On applique la grille tarifaire = prix de base + supplement par terminal
  // supplementaire. On ne recalcule QUE si l'utilisateur n'a pas modifie
  // manuellement les prix dans l'ecran (sinon on respecte son choix).
  try {
    const nbTermAvant = _coursAvant && _coursAvant.terminaux ? String(_coursAvant.terminaux).split('-').filter(Boolean).length : 1;
    const nbTermApres = terminauxAgg ? terminauxAgg.split('-').filter(Boolean).length : 1;
    const prixAvantSaisie = _coursAvant ? (_coursAvant.prix != null ? parseFloat(_coursAvant.prix) : null) : null;
    const prixChAvantSaisie = _coursAvant ? (_coursAvant.prixChauffeur != null ? parseFloat(_coursAvant.prixChauffeur) : null) : null;
    const prixInchange = (prix === prixAvantSaisie) || (prix == null && prixAvantSaisie == null);
    const prixChInchange = (prixChauffeur === prixChAvantSaisie) || (prixChauffeur == null && prixChAvantSaisie == null);

    if(nbTermAvant !== nbTermApres && prixInchange && prixChInchange && client && depart && arrivee) {
      const nouveauTarif = await calculerPrixAutoImport(client, depart, arrivee, vehicule, terminauxAgg);
      if(nouveauTarif) {
        const ancienPrix = prix, ancienPrixCh = prixChauffeur;
        if((nouveauTarif.client||0) > 0) prix = nouveauTarif.client;
        if((nouveauTarif.chauffeur||0) > 0) prixChauffeur = nouveauTarif.chauffeur;
        marge = (prix!=null && prixChauffeur!=null) ? Math.max(0, prix-prixChauffeur) : null;
        const diffTxt = (nbTermApres > nbTermAvant ? '➕' : '➖') + ' ' + Math.abs(nbTermApres - nbTermAvant) + ' terminal(aux)';
        showToast(`💶 Prix recalculé (${diffTxt}) : ${ancienPrix||0}€ → ${prix||0}€ client, ${ancienPrixCh||0}€ → ${prixChauffeur||0}€ chauffeur`);
      }
    }
  } catch(e){ console.warn('recalc prix auto:', e); }

  const maj = {
    depart, arrivee, datetime,
    codeFact: code,
    chauffeur,
    client,
    tel,
    vehicule,
    prix,
    prixChauffeur,
    marge,
    payMode,
    passagers,
    pax: passagers.length||1,
    terminaux: terminauxAgg,
    notes,
    statut: chauffeur ? 'attribuee' : 'nouvelle',
    updatedAt: new Date().toISOString()
  };
  await fbUpdate('courses', id, maj);
  // ★ Synchroniser vers LogiPax (attribution chauffeur, modif infos course)
  try {
    const updated = {...(avant||{}), ...maj, _id:id};
    syncToLogipax(updated, updated.logipaxNumBon ? 'update' : 'insert');
  } catch(e){ console.warn('syncToLogipax:', e); }
  const detail = diffChamps(avant, maj, {
    depart:'Départ', arrivee:'Arrivée', datetime:'Date/heure', codeFact:'Code facturation',
    chauffeur:'Chauffeur', client:'Client', tel:'Téléphone', vehicule:'Véhicule',
    prix:'Prix client', prixChauffeur:'Prix chauffeur', payMode:'Paiement',
    pax:'Nb passagers', notes:'Notes', statut:'Statut'
  });
  const detailPax = diffPassagers(avant?.passagers, passagers);
  const detailComplet = [detail, detailPax].filter(x=>x).join(' | ');
  const nomCourse = avant?.client || depart || id;
  await addLog(detailComplet ? `✏️ Course modifiée : ${nomCourse} — ${detailComplet}` : `✏️ Course modifiée : ${nomCourse} (aucun changement)`);
  // Prévenir le chauffeur assigné de la modification (notification push ciblée).
  // Si le chauffeur a changé, on prévient le NOUVEAU chauffeur.
  try {
    if(chauffeur) {
      const drvIdMod = getChauffeurIdByName(chauffeur);
      const chauffeurAvant = avant ? avant.chauffeur : null;
      const aChange = chauffeurAvant !== chauffeur;
      await sendPushNotification(
        aChange ? `🚗 Course assignée — ${chauffeur}` : `✏️ Course modifiée — ${chauffeur}`,
        `${client||''} | ${fdt(datetime)} | ${depart||''} → ${arrivee||''}`,
        'https://musakdogan-droid.github.io/Simplycab-',
        drvIdMod ? [drvIdMod] : null
      );
    }
  } catch(e) { console.warn('notif modification:', e); }
  // Notifier aussi le staff (dispatch/admin) de la modification.
  try {
    await notifierStaff('✏️ Course modifiée', `${client||''} — ${depart||''} → ${arrivee||''}${datetime?' — '+fdt(datetime):''}`, 'https://mobilea-6tg.pages.dev/#dispatch');
  } catch(e){}
  const _ov = document.getElementById('course-edit-ov');
  if(_ov) _ov.remove();
  // Fermer aussi la modale de course standard si c'est elle qui est ouverte.
  try { if(typeof closeMo === 'function') closeMo('course'); } catch(e){}
  // Mettre à jour l'objet en mémoire tout de suite, pour que renderAll affiche
  // la course modifiée sans attendre l'écoute temps réel (évite le clignotement).
  try {
    const idx = (D.courses||[]).findIndex(x => x._id === id);
    if(idx >= 0) D.courses[idx] = { ...D.courses[idx], ...maj };
  } catch(e){}
  // Rendu immédiat depuis les données déjà en mémoire (l'écoute temps réel a
  // déjà, ou va, mettre à jour D.courses). On évite un await loadAll() complet
  // qui, en se télescopant avec l'écoute, faisait "clignoter" la liste (tout
  // disparaît puis revient). renderAll rafraîchit l'affichage sans vider.
  try { renderAll(); } catch(e){}
  showToast('✓ Course mise à jour');
};

// ── TOUS LES TRANSFERTS D'UN CLIENT ──
window.viewClientCourses = function(clientName) {
  const courses = D.courses.filter(c=>c.client===clientName)
    .sort((a,b)=>new Date(a.datetime)-new Date(b.datetime));
  const color = getClientColor(clientName, courses[0]||{});
  const info = getClientInfo(clientName);

  // Grouper par jour
  const byDay = {};
  courses.forEach(c=>{
    const d = c.datetime?.slice(0,10)||'—';
    if(!byDay[d]) byDay[d] = [];
    byDay[d].push(c);
  });

  const ov = document.createElement('div');
  ov.id = 'client-courses-ov';
  ov.style.cssText = 'position:fixed;inset:0;background:#fff;z-index:620;display:flex;flex-direction:column;overflow:hidden';
  ov.innerHTML = `
    <div style="display:flex;align-items:center;gap:14px;padding:calc(16px + env(safe-area-inset-top, 0px)) 20px 16px;border-bottom:1px solid #f0f0f0">
      <button onclick="document.getElementById('client-courses-ov').remove()" style="background:none;border:none;font-size:30px;cursor:pointer;color:#333;padding:8px">✕</button>
      <div style="width:18px;height:18px;border-radius:5px;background:${color};flex-shrink:0"></div>
      <div>
        <div style="font-size:22px;font-weight:600;color:#1a1a1a">${info.label||clientName}</div>
        <div style="font-size:20px;color:#888">${courses.length} transfert(s)</div>
      </div>
    </div>
    <div style="flex:1;overflow-y:auto;padding:16px 20px 40px">
      ${Object.entries(byDay).map(([day, items])=>{
        const dayLabel = day!=='—' ? new Date(day).toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'}) : 'Sans date';
        return `<div style="font-size:20px;font-weight:700;color:#888;text-transform:uppercase;letter-spacing:1px;margin:18px 0 10px">${dayLabel}</div>`
          + items.map(c=>{
            const time = c.datetime?.slice(11,16)||'—';
            const terms = c.terminaux ? c.terminaux.replace(/CDG/g,'') : '';
            const codeFact = (c.codeFact||c.ref||'').split('/').filter(x=>x&&x!=='NC').slice(0,3).join(' / ');
            return `<div onclick="document.getElementById('client-courses-ov').remove();viewCourseDetail('${c._id}')"
              style="background:${color};border-radius:10px;padding:12px 14px;margin-bottom:6px;cursor:pointer;color:#fff">
              <div style="font-size:20px;font-weight:700;line-height:1.3">${E(raccourcirLieu(c.depart||c.lieu))} / ${E(raccourcirLieu(c.arrivee||c.duree))}${terms?' / '+terms:''}</div>
              <div style="font-size:20px;opacity:0.92;margin-top:3px">${time} à ${codeFact?codeFact+' / ':''}${E(c.chauffeur||'À assigner')}</div>
            </div>`;
          }).join('');
      }).join('')}
      ${!courses.length?'<div style="text-align:center;padding:60px;color:#aaa">Aucun transfert pour ce client</div>':''}
    </div>`;
  document.body.appendChild(ov);
};

window.duplicateCourse = async function(id) {
  const c = D.courses.find(x=>x._id===id);
  if(!c) return;
  const copy = {...c};
  delete copy._id;
  // Une copie est un NOUVEAU transfert : on retire tout ce qui appartient à
  // l'original — chauffeur (sinon la copie restait dans l'app du chauffeur
  // alors qu'elle s'affichait « À assigner »), lien externe (même lien pour 2
  // courses), numéro LogiPax (la copie modifiait le bon LogiPax de l'original),
  // paiement, horaires de déroulement, offres en cours…
  const _aRetirer = ['chauffeurId','chauffeurUid','chauffeurTel','extToken','extChauffeurNom','extChauffeurTel','extIdentifiedAt','extLastLat','extLastLng','extLastPos','lastLat','lastLng',
    'logipaxNumBon','logipaxIdCourse','logipaxSynced','logipaxErreur','logipaxARelancer','logipaxId','paye','payee','payeLe','paiement_statut','paiementId','paiementMode','paiementLe','stripeSessionId','stripePaid','payLienId',
    'accepteePar','accepteeLe','attribueeLe','heureDepose','heureTerminee','terminatedAt','annuleePar','annuleeLe','offerChauffeurId','offerExpiresAt','offerCandidateIds','sousTraitance','vehImmat','vehModele','updatedAt'];
  _aRetirer.forEach(function(k){ delete copy[k]; });
  copy.statut = 'nouvelle';
  copy.chauffeur = '';
  copy.dupliqueDe = id;
  copy.createdAt = new Date().toISOString();
  await fbPush('courses', copy);
  const ov = document.getElementById('course-detail-ov');
  if(ov) ov.remove();
  await loadAll();
  showToast('✓ Course dupliquée');
};

async function updStatut(id, statut) {
  if(!statut)return;
  await fbUpdate('courses', id, {statut, updatedAt:new Date().toISOString()});
  await addLog(`Statut course mis à jour → ${statut}`);
  // Synchroniser vers LogiPax (Deloitte / Magical Shuttle uniquement)
  const c = D.courses.find(x=>x._id===id);
  if(c) { const updated = {...c, statut}; syncToLogipax(updated, updated.logipaxNumBon ? 'update' : 'insert'); }
  await loadAll();
  showToast('Statut mis à jour ✓');
}

async function delCourse(id) {
  const c = D.courses.find(x=>x._id===id);
  const label = c ? `${E(c.client||'')} ${c.datetime?.slice(0,10)||''}` : '';
  // confirm() bloqué sur GitHub Pages - on utilise showConfirm custom
  showConfirm('Supprimer cette course ?', label, async()=>{
    showToast('Suppression...');
    try {
      // ARCHIVAGE AVANT SUPPRESSION : la course entiere est copiee dans
      // /courses_supprimees avec la date, l'auteur et la cle d'origine. Une
      // suppression par erreur reste ainsi recuperable, et on garde une trace
      // de qui a supprime quoi.
      if(c) {
        try {
          await fbPush('courses_supprimees', {
            ...c,
            _cleOrigine: id,
            supprimeeLe: new Date().toISOString(),
            supprimeePar: (SESSION && (SESSION.name || SESSION.email)) || 'inconnu',
            supprimeeParRole: (SESSION && SESSION.role) || '—',
          });
        } catch(eArch) {
          // L'archivage ne doit pas empecher la suppression, mais on previent.
          console.warn('Archivage impossible :', eArch);
        }
      }
      const r = await fetch(`${FB_URL}/courses/${id}.json${authParam(await getAuthToken())}`, {method:'DELETE'});
      if(r.ok) {
        const dtSup = c?.datetime ? new Date(c.datetime).toLocaleString('fr-FR',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'}) : '';
        const paxSup = (c?.passagers||[]).length;
        const trajSup = c ? ((c.depart||c.lieu||'?')+' → '+(c.arrivee||'?')) : '';
        await addLog(`🗑️ Course supprimée : ${c?.client||label||id}${dtSup?' — 📅 '+dtSup:''}${trajSup?' — 📍 '+trajSup:''}${paxSup?' — 👥 '+paxSup+' pax':''}${c?.chauffeur?' — 👤 '+c.chauffeur:''}`);
        await loadAll();
        showToast('✓ Course supprimée (archivée)');
      } else {
        showToast('Erreur : ' + r.status, true);
      }
    } catch(e) {
      showToast('Erreur d\'envoi. Réessayez.', true);
    }
  });
}

// ── CONSULTER / RESTAURER LES COURSES SUPPRIMEES ────────────────────────────
// A appeler depuis la console : listeCoursesSupprimees()
window.listeCoursesSupprimees = async function(n) {
  const rows = await fbGet('courses_supprimees');
  const list = (rows||[]).sort((a,b) =>
    String(b.supprimeeLe||'').localeCompare(String(a.supprimeeLe||'')));
  console.table(list.slice(0, n||30).map(x => ({
    archive: x._id,
    cleOrigine: x._cleOrigine || '—',
    client: x.client || '—',
    date: (x.datetime||'').slice(0,16),
    depart: (x.depart||'').slice(0,25),
    supprimeeLe: (x.supprimeeLe||'').slice(0,19).replace('T',' '),
    par: x.supprimeePar || '—',
  })));
  console.log('Total archivé :', list.length);
  console.log('Pour restaurer : restaurerCourse("<archive>")');
  return list;
};

// Remet une course archivee dans /courses, sous sa cle d'origine si elle est
// connue (les courses LogiPax portent une cle lgpx_* deterministe).
window.restaurerCourse = async function(idArchive) {
  const rows = await fbGet('courses_supprimees');
  const a = (rows||[]).find(x => x._id === idArchive);
  if(!a) { console.error('Archive introuvable :', idArchive); return; }
  const cle = a._cleOrigine;
  const donnees = {...a};
  delete donnees._id; delete donnees._cleOrigine;
  delete donnees.supprimeeLe; delete donnees.supprimeePar; delete donnees.supprimeeParRole;
  if(cle) {
    await fbUpdate('courses', cle, donnees);
    console.log('Course restaurée sous la clé', cle);
  } else {
    const nouveau = await fbPush('courses', donnees);
    console.log('Course restaurée sous une nouvelle clé', nouveau);
  }
  await loadAll();
  showToast('Course restaurée ✓');
};

window.openAssign = function(id) {
  document.getElementById('assign-id').value = id;
  const inp = document.getElementById('assign-drv-input');
  const hid = document.getElementById('assign-drv');
  if(inp) inp.value = '';
  if(hid) hid.value = '';
  buildDriverSelects();
  openMo('assign');
};

// ── LIEN CHAUFFEUR EXTERNE (génération côté dispatch) ───────────────────────
// Crée un token unique pour la course, le stocke, et propose de partager le lien
// (SMS / WhatsApp / copie) à un chauffeur non enregistré.
window.genererLienExterne = async function(id) {
  const c = D.courses.find(x=>x._id===id);
  if(!c) { showToast('Course introuvable', true); return; }

  // Réutiliser le token existant s'il y en a déjà un (le lien reste stable)
  let token = c.extToken;
  if(!token) {
    token = 'ext_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2,12);
    await fbUpdate('courses', id, { extToken: token });
    c.extToken = token;
  }
  // Fix : dans l'app iOS (Capacitor) location.origin = "capacitor://localhost"
  // qui ne marche pas hors de l'app. On force toujours le domaine public
  // mobilea-6tg.pages.dev pour que le lien soit ouvrable par un chauffeur
  // externe depuis n'importe quel navigateur / SMS / WhatsApp.
  const PUBLIC_BASE = 'https://mobilea-6tg.pages.dev/';
  const isCapacitor = (location.protocol === 'capacitor:')
    || (location.origin && location.origin.indexOf('capacitor://') === 0)
    || !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());
  const base = isCapacitor ? PUBLIC_BASE : (location.origin + location.pathname);
  const lien = base + '#c/' + token;

  const d = c.datetime ? c.datetime.slice(8,10)+'/'+c.datetime.slice(5,7)+' '+c.datetime.slice(11,16) : '';
  const dep = c.depart||c.lieu||'';
  const arr = c.arrivee||'';
  const _marque = (c.creePar === 'gerant' && SESSION && SESSION.socNom) ? SESSION.socNom : 'MOBILEA';
  const smsTxt = `Bonjour, course ${_marque} le ${d} : ${dep} vers ${arr}. Suivez et validez ici : ${lien}`;

  // Si un chauffeur est assigné et qu'on a son numéro, on pré-remplit le destinataire.
  // Format international nettoyé (sans espaces) requis par wa.me et sms:.
  let telDest = '';
  try {
    if (c.chauffeur) {
      const info = getChauffeurByName ? getChauffeurByName(c.chauffeur) : null;
      if (info && info.tel) telDest = String(info.tel).replace(/[^0-9+]/g,'');
    }
    // Chauffeur de sous-traitant (sans compte) : son numéro est sur la course.
    if (!telDest && c.chauffeurTel) telDest = String(c.chauffeurTel).replace(/[^0-9+]/g,'');
  } catch(e){}

  // iOS et Android ont des syntaxes SMS légèrement différentes :
  //  - iOS 8+ :  sms:NUMERO&body=TEXTE        (pas de "?")
  //  - Android : sms:NUMERO?body=TEXTE        (ou smsto:NUMERO?body=...)
  // Syntaxe qui marche sur les deux : sms:NUMERO?body= (iOS tolère "?body=" depuis iOS 11).
  // Sans numéro, iOS accepte "sms:?body=..." → l'utilisateur choisit le contact.
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent || '');
  const smsSep = isIOS ? '&' : '?';
  const smsUrl = telDest
    ? `sms:${telDest}${smsSep}body=${encodeURIComponent(smsTxt)}`
    : `sms:${smsSep}body=${encodeURIComponent(smsTxt)}`;
  const waUrl = telDest
    ? `https://wa.me/${telDest.replace(/^\+/,'')}?text=${encodeURIComponent(smsTxt)}`
    : `https://wa.me/?text=${encodeURIComponent(smsTxt)}`;

  const telInfo = telDest ? `<div style="font-size:12px;color:#166534;background:#dcfce7;padding:8px 10px;border-radius:6px;margin-bottom:10px">📱 Envoi direct à <strong>${E(c.chauffeur||'')}</strong> (${E(telDest)})</div>` : '';

  const ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;z-index:999999;background:rgba(0,0,0,0.6);display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML = `
    <div style="background:#fff;border-radius:16px;max-width:440px;width:100%;padding:22px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
        <div style="font-family:'Inter',sans-serif;font-size:17px;font-weight:800;color:#111">🔗 Lien chauffeur externe</div>
        <button onclick="this.closest('div[style*=fixed]').remove()" style="background:#f1f3f5;border:none;border-radius:50%;width:30px;height:30px;cursor:pointer">✕</button>
      </div>
      <div style="font-size:12px;color:#666;margin-bottom:6px">Course : ${E(dep)} → ${E(arr)}</div>
      ${telInfo}
      <div style="background:#f8f9fa;border:1px solid #e8eaed;border-radius:10px;padding:10px;font-size:12px;color:#333;word-break:break-all;margin-bottom:14px">${E(lien)}</div>
      <div style="display:flex;flex-direction:column;gap:8px">
        <button onclick="navigator.clipboard.writeText('${lien.replace(/'/g,"\\'")}').then(()=>showToast('Lien copié ✓'))" style="width:100%;background:#111;border:none;border-radius:10px;padding:13px;color:#fff;font-size:14px;font-weight:700;cursor:pointer">📋 Copier le lien</button>
        <a href="${smsUrl}" style="display:block;text-align:center;width:100%;background:linear-gradient(135deg,#b8860b,#d4a933);border-radius:10px;padding:13px;color:#fff;font-size:14px;font-weight:700;text-decoration:none;box-sizing:border-box">💬 Envoyer par SMS${telDest?' (direct)':''}</a>
        <a href="${waUrl}" target="_blank" rel="noopener" style="display:block;text-align:center;width:100%;background:#25d366;border-radius:10px;padding:13px;color:#fff;font-size:14px;font-weight:700;text-decoration:none;box-sizing:border-box">📱 Envoyer par WhatsApp${telDest?' (direct)':''}</a>
      </div>
      <div style="font-size:11px;color:#999;margin-top:14px;text-align:center">Le lien ouvre l'app MOBILEA Driver si installée, sinon la page web de suivi. Le chauffeur saisit son nom et téléphone et tout remonte ici.</div>
    </div>`;
  document.body.appendChild(ov);
  ov.onclick = e => { if(e.target===ov) ov.remove(); };
};

window.doAssign = async function() {
  const id = document.getElementById('assign-id').value;
  const drv = document.getElementById('assign-drv').value;
  if(!drv){showToast('Sélectionner un chauffeur',true);return;}
  if(!(await docsGarde(drv))) return;

  const c = D.courses.find(x=>x._id===id);
  // Détection conflit
  const conflict = detectConflict(drv, c?.datetime, id, null, c?.depart||c?.lieu);
  if(conflict) {
    const ov = showConflictWarning(conflict, drv);
    document.getElementById('conflict-force-btn').onclick = async () => {
      ov.remove();
      closeMo('assign');
      await _doAssignForce(id, drv, c);
    };
    return;
  }
  closeMo('assign');
  await _doAssignForce(id, drv, c);
};

async function _doAssignForce(id, drv, c) {
  const _uidDrv = chauffeurUidByName(drv);
  await fbUpdate('courses', id, {chauffeur:drv, chauffeurUid:_uidDrv||null, chauffeurId:chauffeurIdByName(drv), statut:'attribuee', updatedAt:new Date().toISOString()});
  // Sécurité : sans chauffeurUid, le chauffeur recevra "Permission denied" en
  // voulant accepter/démarrer. On prévient le staff tout de suite.
  if(!_uidDrv && typeof showToast === 'function') {
    showToast('⚠️ ' + drv + ' n\'a pas de compte connecté : il ne pourra pas accepter. Créez/ouvrez sa fiche avec un mot de passe.', true);
  }
  try { await attachVehicleToCourse(id, drv); } catch(e){ console.warn('attachVehicle:', e); }
  // Envoyer le chauffeur + véhicule à LogiPax (relit la course à jour)
  try {
    const fresh = (await fbGet('courses')).find(x => x._id === id);
    if(fresh) syncToLogipax(fresh, fresh.logipaxNumBon ? 'update' : 'insert');
  } catch(e) { console.warn('sync LogiPax attribution:', e); }
  try { await addLog(`Course "${c?.client||id}" assignée à ${drv}`); } catch(e){}
  const drvId = getChauffeurIdByName(drv);
  await sendPushNotification(
    `🚗 Nouvelle course — ${drv}`,
    `${c?.ref||''} | ${c?.client||''} | ${fdt(c?.datetime)} | ${c?.depart||c?.lieu||''} → ${c?.arrivee||c?.duree||''}`,
    'https://musakdogan-droid.github.io/Simplycab-',
    drvId ? [drvId] : null
  );
  const drvInfo = getChauffeurByName(drv);
  if(drvInfo?.tel && c) await notifyDriverBySMS(drvInfo.tel, c, 'Assignée par dispatch', drvInfo._id);
  // Prévenir le client que son chauffeur est assigné.
  try { await notifierClient(c, '🚕 Chauffeur assigné', drv+' prendra en charge votre course'+(drvInfo && drvInfo.immat?' ('+drvInfo.immat+')':'')+'. Suivez-la en direct dans l\'app.'); } catch(e){}
  await loadAll();
  showToast(`Assigné à ${drv} ✓`);
}

// ══════════════════════════════════════════
// DÉTECTION DE CONFLITS
// ══════════════════════════════════════════
// Détermine la "zone" d'une adresse (pour le chaînage de courses).
function getZoneOf(addr) {
  const s = (addr||'').toLowerCase();
  if(s.includes('cdg')||s.includes('roissy')||s.includes('charles de gaulle')) return 'cdg';
  if(s.includes('orly')) return 'orly';
  if(s.includes('chessy')||s.includes('disney')||s.includes('val d')||s.includes('vallée')||s.includes('serris')||s.includes('bailly')||s.includes('magny')||s.includes('coupvray')) return 'disney';
  if(s.includes('paris')||s.includes('gare du nord')||s.includes('gare de lyon')||s.includes('montparnasse')||s.includes('austerlitz')||s.includes('bercy')||s.includes('75')) return 'paris';
  return 'autre';
}

// Détecte si assigner cette course au chauffeur crée un conflit.
// LOGIQUE DE CHAÎNAGE : un chauffeur occupé peut quand même recevoir une course
// si sa course en cours se termine DANS LA MÊME ZONE que le départ de la
// nouvelle, avec au moins 15 min de marge. Sinon, conflit.
function detectConflict(chauffeurName, datetime, excludeId, coursesOverride, newDepart) {
  if(!chauffeurName || !datetime) return null;
  const newStart = new Date(datetime).getTime();
  const list = coursesOverride || D.courses;
  const MARGE_MIN = 15;          // marge minimale après la fin estimée
  const DUREE_COURSE_DEFAUT = 45; // durée estimée d'une course si inconnue (min)
  const newZone = getZoneOf(newDepart);

  // Parcourir les autres courses actives du chauffeur
  for(const c of list) {
    if(c._id === excludeId) continue;
    if(c.chauffeur !== chauffeurName) continue;
    if(['terminee','annulee','noshow','payee'].includes(c.statut)) continue;
    if(!c.datetime) continue;

    const cStart = new Date(c.datetime).getTime();
    // Fin estimée de la course existante = début + durée estimée
    const cEnd = cStart + DUREE_COURSE_DEFAUT*60000;

    // Cas 1 : la course existante COMMENCE après la nouvelle (dans le futur
    // proche) → risque de conflit si moins de (durée+marge) les sépare.
    if(cStart >= newStart) {
      const gapMin = (cStart - newStart)/60000;
      if(gapMin < DUREE_COURSE_DEFAUT + MARGE_MIN) return c; // pas le temps de faire la nouvelle avant
      continue;
    }

    // Cas 2 : la course existante est AVANT/EN COURS. Le chauffeur pourra-t-il
    // enchaîner ? Il faut : fin estimée + marge <= début nouvelle course, ET
    // même zone (là où il finit = là où commence la nouvelle).
    const margeDispo = (newStart - cEnd)/60000; // minutes entre sa fin et la nouvelle
    // Course terminée depuis longtemps (plus de 3 h avant) : aucun conflit possible.
    // Sans ce garde-fou, une vieille course restée « attribuée » (ex. du 15/11)
    // déclenchait un faux conflit pour un transfert du 01/12.
    if(margeDispo >= 180) continue;
    const cZoneFin = getZoneOf(c.arrivee||c.duree||'');
    const memeZone = (cZoneFin !== 'autre' && cZoneFin === newZone);

    if(margeDispo >= MARGE_MIN && memeZone) {
      continue; // chaînage OK, pas de conflit pour cette course
    }
    // Sinon : conflit (soit pas assez de marge, soit zone différente)
    return c;
  }
  return null;
}

function showConflictWarning(conflict, chauffeurName) {
  const ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.6);z-index:600;display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML = `
    <div style="background:#fff;border-radius:16px;width:460px;max-width:100%;overflow:hidden;box-shadow:0 20px 60px rgba(0,0,0,0.3)">
      <div style="background:#dc2626;padding:16px 20px;display:flex;align-items:center;gap:10px">
        <span style="font-size:24px">⚠️</span>
        <div style="font-family:'Inter',sans-serif;font-size:16px;font-weight:800;color:#fff">Conflit de planning détecté</div>
      </div>
      <div style="padding:20px">
        <div style="font-size:14px;color:#333;margin-bottom:12px">
          <strong>${chauffeurName}</strong> a déjà une course dans les <strong>90 minutes</strong> :
        </div>
        <div style="background:#fef2f2;border:1px solid #fecaca;border-radius:10px;padding:14px;margin-bottom:16px">
          <div style="font-size:13px;font-weight:700;color:#dc2626">${conflict.client||'—'}</div>
          <div style="font-size:12px;color:#666;margin-top:4px">📅 ${fdt(conflict.datetime)}</div>
          <div style="font-size:12px;color:#666">📍 ${conflict.depart||conflict.lieu||'—'} → ${conflict.arrivee||conflict.duree||'—'}</div>
          <div style="font-size:11px;color:#999;margin-top:4px">${sBdg(conflict.statut)}</div>
        </div>
        <div style="font-size:12px;color:#777;margin-bottom:16px">Voulez-vous quand même assigner cette course ?</div>
        <div style="display:flex;gap:8px">
          <button onclick="this.closest('div[style*=fixed]').remove()" 
            style="flex:1;background:#f5f5f5;border:1px solid #e0e0e0;border-radius:10px;padding:12px;font-weight:700;cursor:pointer;color:#333">
            ✕ Annuler
          </button>
          <button id="conflict-force-btn"
            style="flex:1;background:#dc2626;border:none;border-radius:10px;padding:12px;font-weight:700;cursor:pointer;color:#fff">
            ⚠️ Assigner quand même
          </button>
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
  return ov;
}

// ══════════════════════════════════════════
// DISPATCH AUTOMATIQUE
// ══════════════════════════════════════════
window.autoDispatch = function(courseId) {
  const course = D.courses.find(c=>c._id===courseId);
  if(!course){showToast('Course introuvable',true);return;}

  const veh = course.vehicule||'berline';
  const dt = new Date(course.datetime);
  const buffer = 90; // minutes

  // Trouver TOUS les chauffeurs compatibles (véhicule), qu'ils soient libres
  // ou déjà sur une course. Le dispatcheur décide : un chauffeur qui finit une
  // heure avant reste attribuable. On garde juste l'info du conflit pour info.
  // L'utilisateur veut voir TOUS les chauffeurs et decider lui-meme.
  // On n'exclut ni par statut ni par vehicule : on garde juste l'info du
  // conflit (libre / occupe) et une note de compatibilite vehicule pour info.
  const disponibles = D.chauffeurs.slice().map(ch => {
    // On calcule le conflit sans exclure : sert uniquement à l'affichage.
    const name = ch.prenom+(ch.nom?' '+ch.nom:'');
    const conflict = detectConflict(name, course.datetime, courseId, null, course.depart||course.lieu);
    return { ch, conflict };
  }).sort((a,b) => {
    // Les chauffeurs libres d'abord, les occupés ensuite.
    if(!a.conflict && b.conflict) return -1;
    if(a.conflict && !b.conflict) return 1;
    return 0;
  });

  if(!disponibles.length){
    showToast('Aucun chauffeur compatible avec ce véhicule',true);
    return;
  }

  const nbLibres = disponibles.filter(d=>!d.conflict).length;

  // Afficher popup avec chauffeurs disponibles
  const ov = document.createElement('div');
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.5);z-index:500;display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML = `
    <div style="background:#fff;border-radius:16px;width:500px;max-width:100%;max-height:80vh;overflow:hidden;display:flex;flex-direction:column">
      <div style="padding:16px 20px;border-bottom:1px solid #f0f2f5;display:flex;align-items:center;justify-content:space-between">
        <div>
          <div style="font-family:'Inter',sans-serif;font-size:17px;font-weight:800">⚡ Dispatch automatique</div>
          <div style="font-size:12px;color:#777;margin-top:2px">${nbLibres} libre(s) · ${disponibles.length} chauffeur(s) au total</div>
        </div>
        <button onclick="this.closest('div[style*=fixed]').remove()" style="background:#f0f2f5;border:none;border-radius:50%;width:32px;height:32px;cursor:pointer;font-size:16px">✕</button>
      </div>
      <div style="overflow-y:auto;padding:16px;flex:1">
        <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:10px;padding:12px;margin-bottom:14px;font-size:12px;color:#166534">
          <strong>Course :</strong> ${course.client||'—'} • ${fdt(course.datetime)} • ${course.depart||course.lieu||'—'}
        </div>
        <button type="button" onclick="proposerAuxPrioritaires('${courseId}');this.closest('div[style*=fixed]').remove()" style="display:flex;align-items:center;justify-content:center;gap:8px;width:100%;background:linear-gradient(135deg,#fef3c7,#fde68a);border:2px solid #d97706;border-radius:12px;padding:12px;color:#92400e;font-size:14px;font-weight:800;cursor:pointer;margin-bottom:6px">
          ⭐ Proposer aux prioritaires
        </button>
        <div style="font-size:11px;color:#999;margin-bottom:14px;text-align:center">Envoie aux chauffeurs ⭐ uniquement — ne s'ouvre pas aux autres. Idéal à l'avance.</div>
        <div style="position:relative;margin-bottom:12px">
          <i class="fas fa-search" style="position:absolute;left:12px;top:50%;transform:translateY(-50%);color:#aaa;font-size:13px"></i>
          <input type="text" id="ad-search" placeholder="Rechercher un chauffeur…" autocomplete="off"
            oninput="filtrerChauffeursDispatch(this.value)"
            style="width:100%;box-sizing:border-box;padding:11px 12px 11px 36px;border:1.5px solid #e5e7eb;border-radius:10px;font-size:14px;outline:none"
            onfocus="this.style.borderColor='#b8860b'" onblur="this.style.borderColor='#e5e7eb'">
        </div>
        <div id="ad-empty" style="display:none;text-align:center;padding:20px;color:#999;font-size:13px">Aucun chauffeur ne correspond</div>
        <div id="ad-list">
        ${disponibles.map(({ch, conflict})=>{
          const name = ch.prenom+(ch.nom?' '+ch.nom:'');
          const todayCourses = D.courses.filter(c=>c.chauffeur===name&&new Date(c.datetime).toDateString()===dt.toDateString()).length;
          const vehIco = {berline:'🚗',van:'🚐',sprinter:'🚌',bus:'🚍',pmr:'♿',limousine:'🥂',classes:'🖤'}[ch.vehicule]||'🚗';
          const av = name.split(' ').map(n=>n[0]||'').join('').slice(0,2).toUpperCase();
          // Badge selon disponibilité : libre (vert) ou déjà une course (orange).
          // On affiche l'heure de la course en conflit pour que le dispatcheur
          // juge lui-même (ex : elle finit 1h avant → il peut quand même attribuer).
          let badge, hint = '';
          if(conflict) {
            const hConf = conflict.datetime ? conflict.datetime.slice(11,16) : '';
            badge = `<span style="background:#fef3c7;color:#92400e;font-size:11px;font-weight:700;padding:3px 10px;border-radius:20px;white-space:nowrap">⏱ ${hConf||'Occupé'}</span>`;
            hint = ` · <span style="color:#b45309">déjà 1 course ${hConf?'à '+hConf:''}</span>`;
          } else {
            badge = `<span style="background:#dcfce7;color:#166534;font-size:11px;font-weight:700;padding:3px 10px;border-radius:20px">✓ Libre</span>`;
          }
          return `<div data-chname="${name.toLowerCase()}" style="display:flex;align-items:center;gap:12px;padding:12px;background:#f8f9fa;border-radius:12px;margin-bottom:8px;cursor:pointer;border:2px solid transparent;transition:all 0.15s"
            onmouseover="this.style.borderColor='#b8860b'" onmouseout="this.style.borderColor='transparent'"
            onclick="doAutoDispatch('${JA(courseId)}','${JA(name)}',this.closest('div[style*=fixed]'))">
            <div style="width:40px;height:40px;border-radius:50%;background:linear-gradient(135deg,#b8860b,#d4a017);display:flex;align-items:center;justify-content:center;font-family:'Inter',sans-serif;font-weight:800;font-size:14px;color:#fff;flex-shrink:0">${av}</div>
            <div style="flex:1">
              <div style="font-size:14px;font-weight:700;color:#111">${name}</div>
              <div style="font-size:11px;color:#777">${vehIco} ${ch.vehicule||'berline'} • ${todayCourses} course(s) aujourd'hui${hint}</div>
            </div>
            <div style="display:flex;align-items:center;gap:6px">
              ${badge}
              <i class="fas fa-chevron-right" style="color:#aaa;font-size:12px"></i>
            </div>
          </div>`;
        }).join('')}
        </div>
      </div>
    </div>`;
  document.body.appendChild(ov);
};

// Filtre la liste des chauffeurs du dispatch automatique selon la saisie.
window.filtrerChauffeursDispatch = function(q) {
  const term = (q||'').toLowerCase().trim();
  const list = document.getElementById('ad-list');
  const empty = document.getElementById('ad-empty');
  if(!list) return;
  let visibles = 0;
  list.querySelectorAll('[data-chname]').forEach(row => {
    const match = !term || row.getAttribute('data-chname').includes(term);
    row.style.display = match ? '' : 'none';
    if(match) visibles++;
  });
  if(empty) empty.style.display = visibles === 0 ? 'block' : 'none';
};

window.doAutoDispatch = async function(courseId, chauffeurName, overlay) {
  if(!(await docsGarde(chauffeurName))) return;
  if(overlay) overlay.remove();
  await fbUpdate('courses', courseId, {
    chauffeur: chauffeurName,
    chauffeurUid: chauffeurUidByName(chauffeurName),
    chauffeurId: chauffeurIdByName(chauffeurName),
    statut: 'attribuee',
    updatedAt: new Date().toISOString()
  });
  try { await attachVehicleToCourse(courseId, chauffeurName); } catch(e){ console.warn('attachVehicle AD:', e); }
  // Envoyer le chauffeur + véhicule à LogiPax
  try {
    const fresh = (await fbGet('courses')).find(x => x._id === courseId);
    if(fresh) syncToLogipax(fresh, fresh.logipaxNumBon ? 'update' : 'insert');
  } catch(e) { console.warn('sync LogiPax auto-dispatch:', e); }
  const c = D.courses.find(x=>x._id===courseId);
  try { await addLog(`Auto-dispatch : "${c?.client||courseId}" → ${chauffeurName}`); } catch(e){}
  const drvInfoAD = getChauffeurByName(chauffeurName);
  const drvIdAD = drvInfoAD ? drvInfoAD._id : null;
  await sendPushNotification(
    '🚗 Course assignée — '+chauffeurName,
    `${c?.client||''} | ${fdt(c?.datetime)} | ${c?.depart||c?.lieu||''}`,
    'https://musakdogan-droid.github.io/Simplycab-',
    drvIdAD ? [drvIdAD] : null
  );
  await loadAll();
  showToast(`✓ Assigné à ${chauffeurName}`);
};

