  window._catManuelle = false; // nouvelle course → la détection auto reprend la main
  const now = new Date(); now.setMinutes(now.getMinutes()-now.getTimezoneOffset());
  document.getElementById('fc-dt').value = now.toISOString().slice(0,16);
  ['fc-dep','fc-arr','fc-lieu','fc-notes','fc-prix','fc-prix-mad','fc-numveh','fc-tel','fc-prix-chauffeur','fc-commission-pct','fc-commission-pab','fc-frais-annulation'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  { const m=document.getElementById('fc-marge'); if(m) m.textContent='—'; }
  document.querySelectorAll('.term-chk').forEach(c=>c.checked=false);
  document.getElementById('prix-suggest').style.display='none';
