function renderClients() {
  const q=(document.getElementById('cl-q')?.value||'').toLowerCase();
  let list=D.clients.filter(c=>!q||(c.nom||'').toLowerCase().includes(q)||(c.tel||'').includes(q)||(c.siret||'').includes(q));
  const tb=document.getElementById('tb-cl');if(!tb)return;
  if(!list.length){tb.innerHTML=`<tr><td colspan="8" class="t-empty"><i class="fas fa-building"></i><p>Aucun client</p></td></tr>`;return;}
  tb.innerHTML=list.map(c=>{
    const courses=D.courses.filter(x=>x.client===c.nom).length;
    const ca=D.courses.filter(x=>x.client===c.nom&&x.statut==='terminee').reduce((s,x)=>s+(parseFloat(x.prix)||0),0);
    const av=(c.commercial||c.nom||'?').slice(0,2).toUpperCase();
    return`<tr>
      <td>
        <div style="display:flex;align-items:center;gap:8px">
          <div style="width:34px;height:34px;border-radius:50%;background:linear-gradient(135deg,var(--blue),var(--purple));display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;font-family:'Inter',sans-serif;color:#fff;flex-shrink:0">${av}</div>
          <div>
            <div style="font-weight:700;font-size:13px">${E(c.nom)}</div>
            ${c.commercial?`<div style="font-size:10px;color:var(--muted)">${E(c.commercial)}</div>`:''}
            ${c.ref?`<div style="font-size:10px;color:var(--gold)">${E(c.ref)}</div>`:''}
          </div>
        </div>
      </td>
      <td>
        <div style="font-size:11px">${E(c.contact||'—')}</div>
        ${c.poste?`<div style="font-size:10px;color:var(--muted)">${E(c.poste)}</div>`:''}
      </td>
      <td style="font-size:11px">${E(c.tel||'—')}</td>
      <td style="font-size:11px">
        ${c.email?`<div>${E(c.email)}</div>`:''}
        ${c.emailFac?`<div style="color:var(--muted)">${E(c.emailFac)}</div>`:''}
      </td>
      <td>
        ${c.siret?`<div style="font-size:10px;color:var(--muted2)">SIRET: ${E(c.siret)}</div>`:''}
        ${c.tva?`<div style="font-size:10px;color:var(--muted2)">TVA: ${E(c.tva)}</div>`:''}
        ${c.ville?`<div style="font-size:10px;color:var(--muted2)">📍 ${E(c.cp||'')} ${E(c.ville)}</div>`:''}
      </td>
      <td>
        ${sBdg(c.type||'corporate')}
        ${c.modeFac?`<div style="font-size:10px;color:var(--muted);margin-top:3px">${{mensuel:'📅 Mensuel',hebdo:'📅 Hebdo',course:'🚗 Par course',prepaye:'💳 Prépayé'}[c.modeFac]||c.modeFac}</div>`:''}
        ${c.commission?`<div style="font-size:10px;color:var(--gold)">Commission: ${c.commission}%</div>`:''}
        ${c.delai?`<div style="font-size:10px;color:var(--muted)">Délai: ${c.delai}j</div>`:''}
      </td>
      <td><span class="bdg bdg-blue">${courses} course${courses!==1?'s':''}</span><br><span class="text-gold fw7" style="font-size:12px">${ca.toFixed(0)}€</span></td>
      <td>
        <div style="display:flex;gap:5px">
          <button class="btn btn-s btn-xs" onclick="openClientModal('${c._id}')"><i class="fas fa-edit"></i> Modifier</button>
          <button class="btn btn-d btn-xs" onclick="delClient('${c._id}')" aria-label="Supprimer"><i class="fas fa-trash" aria-hidden="true"></i></button>
        </div>
      </td>
    </tr>`;
  }).join('');
}

