window.openTarifModal = function(id) {
  // Remplir la liste des clients
  const sel = document.getElementById('tf-client');
  const clientNames = new Set();
  D.clients.forEach(c => clientNames.add(c.commercial || c.nom));
  const sorted = [...clientNames].filter(Boolean).sort();
  sel.innerHTML = '<option value="">— Choisir un client —</option>' +
    sorted.map(n => `<option value="${E(n)}">${E(n)}</option>`).join('');

  const fields = ['tf-dep','tf-arr','tf-berline','tf-van','tf-sprinter','tf-bus','tf-pmr','tf-limousine',
    'tf-ch-berline','tf-ch-van','tf-ch-sprinter','tf-ch-bus','tf-ch-pmr','tf-ch-limousine','tf-nuit','tf-min','tf-dept-dep','tf-dept-arr'];
  document.getElementById('tf-edit-id').value = id || '';

  if(id) {
    const t = D.tarifs.find(x=>x._id===id);
    if(!t) return;
    document.getElementById('tf-title').textContent = 'Modifier tarif';
    sel.value = t.client || '';
    document.getElementById('tf-dep').value = t.depart || (t.route||'').split('→')[0]?.trim() || '';
    document.getElementById('tf-arr').value = t.arrivee || (t.route||'').split('→')[1]?.trim() || '';
    document.getElementById('tf-cat').value = t.categorie || 'autre';
    document.getElementById('tf-berline').value = t.berline || '';
    document.getElementById('tf-van').value = t.van || '';
    document.getElementById('tf-sprinter').value = t.sprinter || '';
    document.getElementById('tf-limousine').value = t.limousine || '';
    document.getElementById('tf-bus').value = t.bus || '';
    document.getElementById('tf-pmr').value = t.pmr || '';
    document.getElementById('tf-ch-berline').value = t.prixChauffeur_berline || '';
    document.getElementById('tf-ch-van').value = t.prixChauffeur_van || '';
    document.getElementById('tf-ch-sprinter').value = t.prixChauffeur_sprinter || '';
    document.getElementById('tf-ch-limousine').value = t.prixChauffeur_limousine || '';
    document.getElementById('tf-ch-bus').value = t.prixChauffeur_bus || '';
    document.getElementById('tf-ch-pmr').value = t.prixChauffeur_pmr || '';
    document.getElementById('tf-nuit').value = t.nuit || '';
    const tmin=document.getElementById('tf-min'); if(tmin) tmin.value = t.prixMin || '';
    const td1=document.getElementById('tf-dept-dep'); if(td1) td1.value = t.deptDepart || '';
    const td2=document.getElementById('tf-dept-arr'); if(td2) td2.value = t.deptArrivee || '';
  } else {
    document.getElementById('tf-title').textContent = 'Ajouter tarif';
    sel.value = '';
    fields.forEach(f=>{const el=document.getElementById(f);if(el)el.value='';});
    document.getElementById('tf-cat').value = 'autre';
  }
  openMo('tarif');
};

window.saveTarif = async function() {
  if(SESSION.role!=='admin'){showToast('Accès non autorisé',true);return;}
  const client = document.getElementById('tf-client').value.trim();
  const dep = document.getElementById('tf-dep').value.trim();
  const arr = document.getElementById('tf-arr').value.trim();
  if(!client){showToast('Choisir un client',true);return;}
  if(!dep||!arr){showToast('Départ et arrivée obligatoires',true);return;}
  const route = dep + ' → ' + arr;
  const editId = document.getElementById('tf-edit-id').value;

  const data = {
    client:sanitize(client,100), depart:sanitize(dep,200), arrivee:sanitize(arr,200), route:sanitize(route,200),
    categorie: document.getElementById('tf-cat').value,
    berline: document.getElementById('tf-berline').value,
    van: document.getElementById('tf-van').value,
    sprinter: document.getElementById('tf-sprinter').value,
    limousine: document.getElementById('tf-limousine').value,
    bus: document.getElementById('tf-bus').value,
    pmr: document.getElementById('tf-pmr').value,
    prixChauffeur_berline: document.getElementById('tf-ch-berline').value,
    prixChauffeur_van: document.getElementById('tf-ch-van').value,
    prixChauffeur_sprinter: document.getElementById('tf-ch-sprinter').value,
    prixChauffeur_limousine: document.getElementById('tf-ch-limousine').value,
    prixChauffeur_bus: document.getElementById('tf-ch-bus').value,
    prixChauffeur_pmr: document.getElementById('tf-ch-pmr').value,
    nuit: document.getElementById('tf-nuit').value,
    prixMin: document.getElementById('tf-min')?.value||'',
    deptDepart: (document.getElementById('tf-dept-dep')?.value||'').trim(),
    deptArrivee: (document.getElementById('tf-dept-arr')?.value||'').trim(),
    updatedAt: new Date().toISOString()
  };

  closeMo('tarif');
  if(editId) {
    await fbUpdate('tarifs', editId, data);
    showToast('Tarif modifié ✓');
  } else {
    data.createdAt = new Date().toISOString();
    await fbPush('tarifs', data);
    showToast('Tarif ajouté ✓');
  }
  await loadAll();
};

async function delTarif(id){showConfirm('Supprimer ?','',async()=>{await fbDelete('tarifs',id);await loadAll();showToast('Tarif supprimé');});}

async function delClientTarifs(clientName){
  showConfirm(`Supprimer tous les tarifs de ${clientName} ?`,'',async()=>{
    const toDelete = D.tarifs.filter(t=>t.client===clientName);
    for(const t of toDelete) await fbDelete('tarifs',t._id);
    await loadAll();showToast(`Tarifs ${clientName} supprimés`);
  });
}
// ── FACTURATION ──
// ══════════════════════════════════════════
// FACTURATION MENSUELLE PAR CLIENT
// ══════════════════════════════════════════
function populateInvoiceSelects() {
  const clSel = document.getElementById('inv-client');
  if(!clSel) return;

  // Clients (liste unique depuis les courses + clients enregistrés)
  const clientNames = new Set();
  D.clients.forEach(c => clientNames.add(c.commercial || c.nom));
  D.courses.forEach(c => { if(c.client) clientNames.add(c.client); });
  const sorted = [...clientNames].filter(Boolean).sort();
  const currentVal = clSel.value;
  clSel.innerHTML = '<option value="">— Choisir un client —</option>' +
    sorted.map(n => `<option value="${E(n)}">${E(n)}</option>`).join('');
  if(currentVal) clSel.value = currentVal;

  // Par défaut : dates du mois en cours si non déjà remplies
  const ds = document.getElementById('inv-date-start');
  const de = document.getElementById('inv-date-end');
  if(ds && !ds.value) { setInvoiceRange('month'); }
}

// Boutons de période rapide (semaine, mois...)
window.setInvoiceRange = function(type) {
  const ds = document.getElementById('inv-date-start');
  const de = document.getElementById('inv-date-end');
  if(!ds || !de) return;
  const now = new Date();
  const iso = d => d.toISOString().slice(0,10);
  let start, end;
  if(type==='week') {
    const day = (now.getDay()+6)%7; // lundi = 0
    start = new Date(now); start.setDate(now.getDate()-day);
    end = new Date(start); end.setDate(start.getDate()+6);
  } else if(type==='lastweek') {
    const day = (now.getDay()+6)%7;
    end = new Date(now); end.setDate(now.getDate()-day-1);
    start = new Date(end); start.setDate(end.getDate()-6);
  } else if(type==='month') {
    start = new Date(now.getFullYear(), now.getMonth(), 1);
    end = new Date(now.getFullYear(), now.getMonth()+1, 0);
  } else if(type==='lastmonth') {
    start = new Date(now.getFullYear(), now.getMonth()-1, 1);
    end = new Date(now.getFullYear(), now.getMonth(), 0);
  }
  if(start && end) { ds.value = iso(start); de.value = iso(end); }
};

function getInvoiceCourses(clientName, dateStart, dateEnd, opts) {
  // Filtre les courses facturables d'un client entre deux dates (incluses).
  // Par défaut : UNIQUEMENT les courses "terminee" et "noshow" non encore
  // facturées. Si opts.includeAlreadyBilled = true, on inclut aussi
  // "facturee" et "payee" (utile pour réimprimer une ancienne facture).
  opts = opts || {};
  const startTs = dateStart ? new Date(dateStart+'T00:00:00').getTime() : 0;
  const endTs = dateEnd ? new Date(dateEnd+'T23:59:59').getTime() : Infinity;
  const statutsOK = opts.includeAlreadyBilled
    ? ['terminee','facturee','payee','noshow']
    : ['terminee','noshow'];
  return D.courses.filter(c => {
    if(c.client !== clientName) return false;
    if(!statutsOK.includes(c.statut)) return false;
    if(!c.datetime) return false;
    const t = new Date(c.datetime).getTime();
    return t >= startTs && t <= endTs;
  }).sort((a,b)=>new Date(a.datetime)-new Date(b.datetime));
}

// Compte les courses DÉJÀ facturées (facturee/payee) d'un client sur une période.
// Sert à alerter l'utilisateur quand il essaie de refacturer une période.
function countAlreadyBilledInPeriod(clientName, dateStart, dateEnd) {
  const startTs = dateStart ? new Date(dateStart+'T00:00:00').getTime() : 0;
  const endTs = dateEnd ? new Date(dateEnd+'T23:59:59').getTime() : Infinity;
  const dejaFact = D.courses.filter(c => {
    if(c.client !== clientName) return false;
    if(!['facturee','payee'].includes(c.statut)) return false;
    if(!c.datetime) return false;
    const t = new Date(c.datetime).getTime();
    return t >= startTs && t <= endTs;
  });
  // Grouper par numéro de facture pour afficher les différentes factures
  const parFacture = {};
  dejaFact.forEach(c => {
    const ref = c.factureRef || '(sans référence)';
    parFacture[ref] = (parFacture[ref]||0) + 1;
  });
  return { total: dejaFact.length, parFacture };
}

function buildInvoiceData() {
  const clientName = document.getElementById('inv-client').value;
  const dateStart = document.getElementById('inv-date-start').value;
  const dateEnd = document.getElementById('inv-date-end').value;
  if(!clientName) { showToast('Choisir un client', true); return null; }
  if(!dateStart || !dateEnd) { showToast('Choisir la période (date début et date fin)', true); return null; }
  if(dateStart > dateEnd) { showToast('La date de début doit être avant la date de fin', true); return null; }

  // ★ Courses NON ENCORE facturées (statut terminee/noshow) sur la période
  const courses = getInvoiceCourses(clientName, dateStart, dateEnd);

  // Vérifier s'il existe déjà des courses facturées sur ce créneau
  const deja = countAlreadyBilledInPeriod(clientName, dateStart, dateEnd);

  if(!courses.length) {
    // Aucune course à facturer — soit vraiment rien, soit tout est déjà facturé
    if(deja.total > 0) {
      const refs = Object.keys(deja.parFacture).map(ref => `• ${ref} (${deja.parFacture[ref]} course${deja.parFacture[ref]>1?'s':''})`).join('\n');
      alert(`⚠️ Aucune nouvelle course à facturer sur cette période.\n\n`
        + `${deja.total} course(s) sont déjà facturée(s) :\n${refs}\n\n`
        + `Pour réimprimer une ancienne facture, utilisez le menu "Factures" dans l'historique.`);
    } else {
      showToast('Aucune course terminée sur cette période', true);
    }
    return null;
  }

  // Avertir si certaines courses ont déjà été facturées (on les exclut automatiquement)
  if(deja.total > 0) {
    const refs = Object.keys(deja.parFacture).join(', ');
    showToast(`ℹ️ ${deja.total} course(s) déjà facturée(s) ignorée(s) — facture(s) : ${refs}`);
  }

  const clientObj = D.clients.find(c => (c.commercial===clientName) || (c.nom===clientName));
  const fmtD = d => { const p=d.split('-'); return p[2]+'/'+p[1]+'/'+p[0]; };
  const periodeLabel = `du ${fmtD(dateStart)} au ${fmtD(dateEnd)}`;

  let totalTTC = 0;
  const lines = courses.map(c => {
    let ttc = parseFloat(c.prix) || 0;
    const w = calcWaitFees(c);
    const waitFee = w ? w.clientFee : 0;
    ttc += waitFee;
    totalTTC += ttc;
    const htv = ht(ttc);
    return {
      date: fdt(c.datetime),
      trajet: `${E(c.depart||c.lieu||'—')} → ${E(c.arrivee||c.duree||'—')}`,
      chauffeur: c.chauffeur||'—',
      ref: c.ref||'',
      waitFee,
      waitMin: w ? w.waitMin : 0,
      co2: (function(){ try { const r = co2Course(c); return r && r.kg != null ? r : null; } catch(e){ return null; } })(),
      ht: htv,
      tva: ttc-htv,
      ttc
    };
  });
  const totalHT = ht(totalTTC);
  const totalTVA = totalTTC - totalHT;
  const numFacture = `BL-${dateStart.replace(/-/g,'')}-${(clientName.replace(/[^A-Z0-9]/gi,'').slice(0,4)||'CLI').toUpperCase()}`;
  const _co2L = lines.filter(l => l.co2);
  const co2Total = { kg: _co2L.reduce((a,l)=>a+l.co2.kg,0), km: _co2L.reduce((a,l)=>a+l.co2.km,0), n: _co2L.length, total: lines.length };

  return { clientName, clientObj, dateStart, dateEnd, periodeLabel, moisLabel:periodeLabel, courses, lines, totalHT, totalTVA, totalTTC, numFacture, co2Total };
}

