// ── Affichage de documents imprimables DANS l'app (window.open ne marche pas
// dans l'app mobile MOBILEA, qui n'a pas de navigateur pour ouvrir un onglet) ──
window.openPrintableDoc = function(html) {
  const existing = document.getElementById('printable-doc-overlay');
  if(existing) existing.remove();

  const overlay = document.createElement('div');
  overlay.id = 'printable-doc-overlay';
  // z-index très élevé : doit passer AU-DESSUS de la course plein écran
  // (coursefull-overlay = 9999998), sinon le bon de commande s'ouvre dessous
  // et on ne le voit pas tant qu'on n'a pas quitté la course.
  overlay.style.cssText = 'position:fixed;inset:0;z-index:2147483000;background:#525659;display:flex;flex-direction:column';

  const bar = document.createElement('div');
  bar.style.cssText = 'flex-shrink:0;background:#1a1a1a;padding:10px 14px;padding-top:calc(10px + env(safe-area-inset-top));display:flex;justify-content:flex-end;gap:10px;box-shadow:0 2px 8px rgba(0,0,0,0.3)';
  bar.innerHTML = '<button id="printable-doc-print" style="background:#b8860b;border:none;border-radius:8px;padding:10px 16px;color:#fff;font-weight:700;font-size:13px;cursor:pointer">🖨️ Imprimer / PDF</button>'
    + '<button id="printable-doc-close" style="background:#444;border:none;border-radius:8px;padding:10px 16px;color:#fff;font-weight:700;font-size:13px;cursor:pointer">✕ Fermer</button>';

  const iframe = document.createElement('iframe');
  iframe.style.cssText = 'flex:1;border:none;width:100%;background:#fff';

  overlay.appendChild(bar);
  overlay.appendChild(iframe);
  document.body.appendChild(overlay);
  iframe.srcdoc = html;

  document.getElementById('printable-doc-close').onclick = function() { overlay.remove(); };
  document.getElementById('printable-doc-print').onclick = async function() {
    const estNatif = !!(window.Capacitor && window.Capacitor.isNativePlatform && window.Capacitor.isNativePlatform());

    // ── APP NATIVE (iPhone) : window.open et iframe.print sont bloqués. ──
    // On génère un fichier et on ouvre le PARTAGE natif iOS, qui propose
    // « Imprimer », « Enregistrer dans Fichiers », « Envoyer », etc.
    if (estNatif) {
      // 1) Partage natif via le plugin Capacitor Share s'il est présent.
      try {
        var Share = (window.Capacitor.Plugins && window.Capacitor.Plugins.Share) || null;
        var Fs = (window.Capacitor.Plugins && window.Capacitor.Plugins.Filesystem) || null;
        if (Share && Fs) {
          // Écrire le HTML en fichier temporaire, puis le partager.
          var nomFichier = 'mobilea-doc-' + Date.now() + '.html';
          var w = await Fs.writeFile({ path: nomFichier, data: html, directory: 'CACHE', encoding: 'utf8' });
          await Share.share({ title: 'Document MOBILEA', url: w.uri, dialogTitle: 'Imprimer ou enregistrer' });
          return;
        }
      } catch(e) {}
      // 2) Repli : Web Share API (dispo dans les WebView iOS récentes).
      try {
        if (navigator.share) {
          var blob = new Blob([html], { type: 'text/html' });
          var file = new File([blob], 'document-mobilea.html', { type: 'text/html' });
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({ files: [file], title: 'Document MOBILEA' });
            return;
          }
          await navigator.share({ title: 'Document MOBILEA', text: 'Document MOBILEA' });
          return;
        }
      } catch(e) {}
      // 3) Dernier repli : tenter l'impression de l'iframe.
      try { iframe.contentWindow.focus(); iframe.contentWindow.print(); return; }
      catch(e){ if(typeof showToast==='function') showToast('Utilisez le bouton Partager de votre iPhone pour imprimer', true); return; }
    }

    // ── WEB (ordinateur / navigateur) : méthode classique. ──
    let printed = false;
    try {
      const win = window.open('', '_blank');
      if(win && win.document) {
        win.document.open();
        win.document.write(html);
        win.document.close();
        printed = true;
        setTimeout(function(){ try { win.focus(); win.print(); } catch(e){} }, 500);
      }
    } catch(e) {}
    if(!printed) {
      try {
        iframe.contentWindow.focus();
        setTimeout(function(){
          try { iframe.contentWindow.print(); }
          catch(e3) { if(typeof showToast==='function') showToast('Pour imprimer : appuyez sur Partager puis « Imprimer »', true); }
        }, 300);
      } catch(e2) {
        if(typeof showToast==='function') showToast('Pour imprimer : appuyez sur Partager puis « Imprimer »', true);
      }
    }
  };
};

