// ═══════════════════════════════════════════════════════════════════
// MARQUER LES COURSES COMME FACTURÉES (sceller la facture)
// Propose à l'utilisateur, après génération du PDF, de passer les courses
// de "terminee" à "facturee" + stocker la référence de facture. Cela
// garantit qu'elles ne seront PAS incluses dans une future facturation.
// ═══════════════════════════════════════════════════════════════════
function _proposerMarquerFacturees(inv) {
  if(!inv || !inv.courses || !inv.courses.length) return;
  // Si tous les courses sont déjà marquées facturée, inutile d'insister
  const aMarquer = inv.courses.filter(c => c.statut === 'terminee' || c.statut === 'noshow');
  if(!aMarquer.length) return;

  const msg = `✅ Facture ${inv.numFacture} générée.\n\n`
    + `Voulez-vous MARQUER les ${aMarquer.length} course(s) comme FACTURÉES ?\n\n`
    + `Si oui, elles ne pourront plus être incluses dans une future facture (évite les doubles facturations).\n\n`
    + `• Cliquez OK pour sceller la facture\n`
    + `• Cliquez Annuler si vous voulez d'abord vérifier le PDF`;
  if(!confirm(msg)) {
    showToast('ℹ️ Facture non scellée — les courses restent facturables. Repassez par "Générer PDF" quand vous êtes prêt.');
    return;
  }

  // Marquer en batch via Firebase multi-path update (rapide)
  (async () => {
    showToast(`Marquage de ${aMarquer.length} course(s)…`);
    const nowIso = new Date().toISOString();
    try {
      if(window.fbDB) {
        const updates = {};
        aMarquer.forEach(c => {
          updates['courses/'+c._id+'/statut'] = 'facturee';
          updates['courses/'+c._id+'/factureRef'] = inv.numFacture;
          updates['courses/'+c._id+'/factureAt'] = nowIso;
        });
        await window.fbDB.ref().update(updates);
      } else {
        for(const c of aMarquer) {
          await fbUpdate('courses', c._id, { statut:'facturee', factureRef:inv.numFacture, factureAt:nowIso });
        }
      }
      // Mettre à jour localement pour affichage immédiat
      aMarquer.forEach(c => {
        const local = D.courses.find(x => x._id === c._id);
        if(local) { local.statut = 'facturee'; local.factureRef = inv.numFacture; local.factureAt = nowIso; }
      });
      try { await addLog(`📄 Facture ${inv.numFacture} scellée — ${aMarquer.length} course(s) marquée(s) facturée(s) (${inv.clientName})`); } catch(e){}
      showToast(`✅ Facture ${inv.numFacture} scellée (${aMarquer.length} courses)`);
      await loadAll();
    } catch(e) {
      console.warn('Marquage facturée échoué:', e);
      showToast('Erreur marquage facturée — réessayez', true);
    }
  })();
}
window._proposerMarquerFacturees = _proposerMarquerFacturees;

function renderFact() {
  // Factures reçues des chauffeurs
  const tbFc = document.getElementById('tb-fac-ch');
  const fcCount = document.getElementById('fc-count');
  if(tbFc) {
    const facs = D.factures_chauffeurs || [];
    if(fcCount) fcCount.textContent = facs.length;
    if(!facs.length) {
      tbFc.innerHTML = `<tr><td colspan="8" class="t-empty"><i class="fas fa-file-invoice"></i><p>Aucune facture reçue</p></td></tr>`;
    } else {
      tbFc.innerHTML = facs.map(f=>`<tr>
        <td>${f.createdAt?new Date(f.createdAt).toLocaleDateString('fr-FR'):'—'}</td>
        <td>${E(f.chauffeur||'—')}</td>
        <td>${E(f.societe||'—')}</td>
        <td>${E(f.moisLabel||'—')}</td>
        <td style="text-align:center">${f.nbCourses||0}</td>
        <td style="font-weight:700;color:var(--gold)">${(f.totalTTC||0).toFixed(2)}€</td>
        <td style="font-size:10px;color:var(--muted)">${E(f.numFacture||'')}</td>
        <td><span class="bdg ${f.statut==='payee'?'bdg-green':'bdg-gold'}">${f.statut==='payee'?'Payée':'Reçue'}</span></td>
      </tr>`).join('');
    }
  }

  const s=document.getElementById('fac-s')?.value||'';
  const list=D.courses.filter(c=>['terminee','facturee','payee','noshow'].includes(c.statut)&&(!s||c.statut===s));
  const totalTTC=list.reduce((x,c)=>x+prixFacture(c),0);
  const totalHT=ht(totalTTC);
  const e1=document.getElementById('fac-ht');const e2=document.getElementById('fac-ttc');
  if(e1)e1.textContent=`HT : ${totalHT.toFixed(0)}€`;
  if(e2)e2.textContent=`TTC : ${totalTTC.toFixed(0)}€`;
  const tb=document.getElementById('tb-fac');if(!tb)return;
  if(!list.length){tb.innerHTML=`<tr><td colspan="11" class="t-empty"><i class="fas fa-file-invoice"></i><p>Aucune facture</p></td></tr>`;return;}
  let n=1;
  tb.innerHTML=list.map(c=>{
    const ttc=parseFloat(c.prix)||0;const htv=ht(ttc);const tva=ttc-htv;
    const num=`BL-${new Date().getFullYear()}-${String(n++).padStart(4,'0')}`;
    return`<tr>
      <td class="text-gold fw7 ff-syne" style="font-size:11px">${num}</td>
      <td><strong style="font-size:12px">${E(c.client||'—')}</strong></td>
      <td style="font-size:11px">${E(c.chauffeur||'—')}</td>
      <td style="font-size:10px">${fdt(c.datetime)}</td>
      <td>${tBdg(c.type)}</td>
      <td style="font-size:10px;max-width:100px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${(c.depart||c.lieu||'').slice(0,18)}→${(c.arrivee||c.duree||'').slice(0,12)}</td>
      <td style="font-size:11px">${htv.toFixed(2)}€</td>
      <td style="font-size:11px;color:var(--muted2)">${tva.toFixed(2)}€</td>
      <td class="text-gold fw7">${ttc.toFixed(2)}€</td>
      <td>${sBdg(c.statut)}</td>
      <td>
        <button class="btn btn-ghost btn-xs" onclick="printFac('${c._id}','${num}')" aria-label="Imprimer"><i class="fas fa-print" aria-hidden="true"></i></button>
        ${(ttc>0 && !stripeCoursePayee(c)) ? `<button class="btn btn-ghost btn-xs" onclick="payLienCourse('${c._id}')" title="Lien de paiement par carte" aria-label="Lien de paiement"><i class="fas fa-credit-card" aria-hidden="true"></i></button>` : (c.paiement_mode==='carte_en_ligne' ? '<span title="Payé par carte en ligne" style="font-size:12px">💳✓</span>' : '')}
        <button class="btn btn-g btn-xs" onclick="updStatut('${c._id}','payee')" aria-label="Valider"><i class="fas fa-check" aria-hidden="true"></i></button>
      </td>
    </tr>`;
  }).join('');
}

