// Message « système » du client vers le support (pourboire, note, profil) :
// rangé dans SON fil de conversation pour que le dispatch le retrouve dans la
// Messagerie (et pas seulement via la notification push).
function _msgClientVersSupport(obj, texte){
  var key = String(SESSION.uid || SESSION.name || 'inconnu').replace(/[^a-zA-Z0-9_-]/g,'_');
  return Object.assign({}, obj, {
    conv: 'client_' + key, text: texte, from: SESSION.uid || SESSION.name,
    fromName: SESSION.name || SESSION.societe || 'Client', fromRole: SESSION.role,
    clientName: SESSION.societe || SESSION.name, at: new Date().toISOString(), read: false
  });
}

// ── #1 Réserver pour quelqu'un d'autre ───────────────────────────────────
window.cbToggleOther = function(show){
  var z = document.getElementById('cb-other-fields'); if(z) z.style.display = show ? 'block' : 'none';
};

// ── #3 Arrêts intermédiaires ──────────────────────────────────────────────
window._cbEtapes = window._cbEtapes || [];
window.cbAddEtape = function(){
  if(window._cbEtapes.length >= 3){ showToast('3 arrêts maximum', true); return; }
  window._cbEtapes.push({ adresse:'' });
  cbRenderEtapes();
};
window.cbRemoveEtape = function(i){ window._cbEtapes.splice(i,1); cbRenderEtapes(); };
window.cbRenderEtapes = function(){
  var box = document.getElementById('cb-etapes-list'); if(!box) return;
  box.innerHTML = (window._cbEtapes||[]).map(function(e,i){
    return '<div style="display:flex;gap:6px;align-items:center">'
      + '<input type="text" id="cb-etape-'+i+'" value="'+(e.adresse||'').replace(/"/g,'&quot;')+'" maxlength="200" placeholder="Arrêt '+(i+1)+'" oninput="window._cbEtapes['+i+'].adresse=this.value" style="flex:1;background:var(--dark);border:1px solid var(--border2);border-radius:var(--r-sm);padding:9px;color:var(--white);font-size:13px;outline:none">'
      + '<button type="button" onclick="cbRemoveEtape('+i+')" style="background:var(--card2);border:1px solid var(--border2);border-radius:8px;width:34px;height:34px;color:#e57373;cursor:pointer;flex-shrink:0">✕</button>'
      + '</div>';
  }).join('');
  var addBtn = document.getElementById('cb-etape-add');
  if(addBtn) addBtn.style.display = (window._cbEtapes||[]).length >= 3 ? 'none' : 'block';
  // Autocomplete Google sur les nouveaux champs
  (window._cbEtapes||[]).forEach(function(e,i){
    try { var el=document.getElementById('cb-etape-'+i); if(el && !el.dataset.placesReady) attachPlaces('cb-etape-'+i); } catch(err){}
  });
};

// ── #4 Note + avis du chauffeur ───────────────────────────────────────────
function clRatingsStore(){ try { return JSON.parse(localStorage.getItem('mobilea_ratings')||'{}'); } catch(e){ return {}; } }
window.clHasRated = function(id){ return clRatingsStore()[id] != null; };
window.clRatingOf = function(id){ var r=clRatingsStore()[id]; return r ? (r.note||r) : ''; };
window.clNoterChauffeur = function(id){
  var c = (D.courses||[]).find(function(x){return x._id===id;}) || {};
  var old=document.getElementById('cl-note-ov'); if(old) old.remove();
  var ov=document.createElement('div');
  ov.id='cl-note-ov';
  ov.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;padding:18px';
  ov.innerHTML =
      '<div style="background:var(--card);width:100%;max-width:420px;border-radius:16px;padding:22px;text-align:center">'
    +   '<div style="font-family:Inter,sans-serif;font-size:18px;font-weight:800;color:var(--white);margin-bottom:4px">⭐ Noter votre chauffeur</div>'
    +   '<div style="font-size:13px;color:var(--muted);margin-bottom:16px">'+(c.chauffeur?E(c.chauffeur):'Course')+(c.ref?' · '+E(c.ref):'')+'</div>'
    +   '<div id="cl-stars" style="display:flex;justify-content:center;gap:8px;margin-bottom:16px">'
    +     [1,2,3,4,5].map(function(n){ return '<span data-n="'+n+'" onclick="clSetStars('+n+')" style="font-size:34px;cursor:pointer;filter:grayscale(1);opacity:.5">⭐</span>'; }).join('')
    +   '</div>'
    +   '<input type="hidden" id="cl-note-val" value="0">'
    +   '<textarea id="cl-note-comment" rows="3" maxlength="300" placeholder="Un commentaire (optionnel)" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:11px;color:var(--white);font-size:13px;outline:none;resize:none;margin-bottom:14px;box-sizing:border-box"></textarea>'
    +   '<div style="display:flex;gap:8px">'
    +     '<button onclick="document.getElementById(\'cl-note-ov\').remove()" style="flex:1;background:var(--card2);border:1px solid var(--border2);border-radius:10px;padding:12px;color:var(--white);font-weight:700;cursor:pointer">Annuler</button>'
    +     '<button onclick="clNoterValider(\''+id+'\')" style="flex:2;background:var(--gold);border:none;border-radius:10px;padding:12px;color:#111;font-weight:800;cursor:pointer">Envoyer</button>'
    +   '</div>'
    + '</div>';
  document.body.appendChild(ov);
  ov.onclick=function(e){ if(e.target===ov) ov.remove(); };
};
window.clSetStars = function(n){
  document.getElementById('cl-note-val').value = n;
  var stars = document.querySelectorAll('#cl-stars span');
  stars.forEach(function(s){ var v=parseInt(s.dataset.n); s.style.filter = v<=n?'none':'grayscale(1)'; s.style.opacity = v<=n?'1':'.5'; });
};
window.clNoterValider = async function(id){
  var note = parseInt(document.getElementById('cl-note-val').value)||0;
  if(note<1){ showToast('Sélectionnez une note', true); return; }
  var comment = (document.getElementById('cl-note-comment').value||'').trim();
  var c = (D.courses||[]).find(function(x){return x._id===id;}) || {};
  var ov=document.getElementById('cl-note-ov'); if(ov) ov.remove();
  try { var r=clRatingsStore(); r[id]={note:note,comment:comment,at:new Date().toISOString()}; localStorage.setItem('mobilea_ratings', JSON.stringify(r)); } catch(e){}
  try { await fbPush('messages', _msgClientVersSupport({ type:'note_chauffeur', courseId:id, ref:c.ref||'', client:SESSION.name, chauffeur:c.chauffeur||'', note:note, commentaire:comment, to:'staff', createdAt:new Date().toISOString(), lu:false }, '⭐ Note '+note+'/5 pour '+(c.chauffeur||'le chauffeur')+(comment?' — « '+comment+' »':''))); } catch(e){}
  try { await sendPushNotification('⭐ Avis client', (SESSION.name||'Client')+' note '+(c.chauffeur||'le chauffeur')+' : '+note+'/5'+(comment?' — '+comment:''), null, null, { key:'role', value:'staff' }); } catch(e){}
  showToast('⭐ Merci pour votre note !');
  try { renderClientPortal(); } catch(e){}
};

// ── #5 Code promo / parrainage ────────────────────────────────────────────
window.clReferralCode = function(){
  var seed = (SESSION.clientUser || SESSION.name || SESSION.email || 'MOBILEA')+'';
  var h=0; for(var i=0;i<seed.length;i++){ h=((h<<5)-h+seed.charCodeAt(i))|0; }
  return 'MOB-' + Math.abs(h).toString(36).toUpperCase().slice(0,6);
};

