    +   '<div class="fld"><label>Téléphone</label><input type="tel" id="cpf-tel" maxlength="30" value="'+((p.tel||SESSION.tel||'')).replace(/"/g,'&quot;')+'" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:11px;color:var(--white);font-size:14px;outline:none;box-sizing:border-box"></div>'
