window.clSaveProfil = async function(){
  var nom=(document.getElementById('cpf-nom').value||'').trim();
  var tel=(document.getElementById('cpf-tel').value||'').trim();
  var email=(document.getElementById('cpf-email').value||'').trim();
  try { localStorage.setItem('mobilea_client_profil', JSON.stringify({nom:nom,tel:tel,email:email})); } catch(e){}
  try { await fbPush('messages', _msgClientVersSupport({ type:'profil_update', client:SESSION.name, clientUser:SESSION.clientUser||'', nom:nom, tel:tel, email:email, to:'staff', createdAt:new Date().toISOString(), lu:false }, '👤 Mise à jour du profil — nom : '+nom+' · tél : '+tel+' · email : '+email)); } catch(e){}
  try { await sendPushNotification('👤 Mise à jour profil client', (SESSION.name||'Client')+' a modifié ses coordonnées (tel: '+tel+')', null, null, { key:'role', value:'staff' }); } catch(e){}
  showToast('✓ Profil enregistré — transmis à l\'équipe');
};

// Politique de confidentialité (lien exigé par l'App Store, règle 5.1.1(i)).
window.MOBILEA_PRIVACY_URL = window.MOBILEA_PRIVACY_URL || 'https://musakdogan-droid.github.io/mobilea-privacy/';
window.mobileaOuvrirConfidentialite = function(){
  var u = window.MOBILEA_PRIVACY_URL;
  try {
    var B = window.Capacitor && window.Capacitor.Plugins && window.Capacitor.Plugins.Browser;
    if(B && B.open){ B.open({ url:u }); return; }
  } catch(e){}
  window.open(u, '_blank');
};

// ── Suppression du compte client (exigence App Store 5.1.1(v)) ──────────
// Particulier : suppression immédiate (profil + cartes enregistrées + compte
// de connexion). Les courses/factures passées sont conservées pour les
// obligations comptables légales. Partenaire (compte créé par MOBILEA) :
// demande transmise à l'équipe.
window.clOuvrirSuppressionCompte = function(){
  var old=document.getElementById('cl-del-ov'); if(old) old.remove();
  var estPart = !!(SESSION && SESSION.isPartenaire);
  var ov=document.createElement('div');
  ov.id='cl-del-ov';
  ov.style.cssText='position:fixed;inset:0;z-index:100000;background:rgba(0,0,0,.7);display:flex;align-items:center;justify-content:center;padding:16px';
  ov.innerHTML =
      '<div style="background:var(--card);width:100%;max-width:440px;border-radius:16px;padding:20px;border:1px solid rgba(229,115,115,.4)">'
    +   '<h2 style="font-size:17px;font-weight:800;color:#e57373;margin:0 0 10px">🗑️ Supprimer mon compte</h2>'
    + (estPart
      ? '<p style="color:var(--muted);font-size:13px;line-height:1.5;margin:0 0 16px">Votre compte entreprise est géré par MOBILEA. Votre demande de suppression sera transmise à notre équipe, qui la traitera et vous confirmera par email.</p>'
        + '<button id="cl-del-go" onclick="clConfirmerSuppressionCompte()" style="width:100%;background:#e57373;border:none;border-radius:12px;padding:13px;color:#111;font-weight:800;cursor:pointer;margin-bottom:8px">Envoyer la demande de suppression</button>'
      : '<p style="color:var(--muted);font-size:13px;line-height:1.5;margin:0 0 12px">Cette action est <b style="color:var(--white)">définitive</b> : votre profil, vos cartes enregistrées et votre accès seront supprimés. Les factures de vos courses passées sont conservées uniquement pour nos obligations comptables légales.</p>'
        + '<div class="fld"><label>Confirmez avec votre mot de passe</label><input type="password" id="cl-del-pass" autocomplete="current-password" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:11px;color:var(--white);font-size:14px;outline:none;box-sizing:border-box"></div>'
        + '<div id="cl-del-err" style="color:#e57373;font-size:12px;min-height:16px;margin:6px 0 10px"></div>'
        + '<button id="cl-del-go" onclick="clConfirmerSuppressionCompte()" style="width:100%;background:#e57373;border:none;border-radius:12px;padding:13px;color:#111;font-weight:800;cursor:pointer;margin-bottom:8px">Supprimer définitivement</button>')
    +   '<button onclick="document.getElementById(\'cl-del-ov\').remove()" style="width:100%;background:transparent;border:1px solid var(--border2);border-radius:12px;padding:12px;color:var(--white);cursor:pointer">Annuler</button>'
    + '</div>';
  document.body.appendChild(ov);
  ov.onclick=function(e){ if(e.target===ov) ov.remove(); };
};

window.clConfirmerSuppressionCompte = async function(){
  var btn=document.getElementById('cl-del-go');
  var errEl=document.getElementById('cl-del-err');
  var setErr=function(t){ if(errEl) errEl.textContent=t; else showToast(t); };
  if(!SESSION || SESSION.role!=='client') return;
  // Partenaire : simple demande à l'équipe
  if(SESSION.isPartenaire){
    if(btn){ btn.disabled=true; btn.textContent='Envoi…'; }
    try { await fbPush('messages', _msgClientVersSupport({ type:'suppression_compte', client:SESSION.name, clientUser:SESSION.clientUser||'', email:SESSION.email||'', to:'staff', createdAt:new Date().toISOString(), lu:false }, '🗑️ Demande de suppression du compte entreprise ('+(SESSION.societe||SESSION.name||'')+' — '+(SESSION.email||'')+')')); } catch(e){}
    try { await sendPushNotification('🗑️ Demande de suppression de compte', (SESSION.societe||SESSION.name||'Partenaire')+' demande la suppression de son compte', null, null, { key:'role', value:'staff' }); } catch(e){}
    var o=document.getElementById('cl-del-ov'); if(o) o.remove();
    showToast('✓ Demande envoyée — notre équipe vous confirmera la suppression par email');
    return;
  }
  var pass=(document.getElementById('cl-del-pass')||{}).value||'';
  if(!pass){ setErr('Saisissez votre mot de passe'); return; }
  var user = window.fbAuth && window.fbAuth.currentUser;
  if(!user){ setErr('Session expirée : reconnectez-vous puis réessayez.'); return; }
  var uid = user.uid;
  // Bloquer s'il reste une course en cours / à venir (sinon le chauffeur
  // viendrait chercher un client sans compte).
  var actifs=['nouvelle','en_attente','attribuee','acceptee','en_route','sur_place','onboard','offre_en_cours'];
  var enCours=(D.courses||[]).filter(function(c){ return (c.createdByUid===uid || (SESSION.clientUser && c.clientUser===SESSION.clientUser)) && actifs.indexOf(c.statut)>=0; });
  if(enCours.length){ setErr('Vous avez '+enCours.length+' course(s) en cours ou à venir. Annulez-les (ou attendez la fin) avant de supprimer votre compte.'); return; }
  if(btn){ btn.disabled=true; btn.textContent='Suppression…'; }
  try {
    // 1) Ré-authentification (Firebase l'exige pour supprimer un compte)
    var cred = firebase.auth.EmailAuthProvider.credential(user.email || SESSION.email, pass);
    await user.reauthenticateWithCredential(cred);
  } catch(e){
    if(btn){ btn.disabled=false; btn.textContent='Supprimer définitivement'; }
    setErr((e && (e.code==='auth/wrong-password'||e.code==='auth/invalid-credential')) ? 'Mot de passe incorrect' : ('Vérification impossible : '+((e&&e.message)||e)));
    return;
  }
  // 2) Cartes enregistrées chez Stripe (au mieux)
  try {
    var lst = await _ccApi('list');
    for(var i=0;i<((lst&&lst.cards)||[]).length;i++){ try { await _ccApi('delete', { paymentMethodId: lst.cards[i].id }); } catch(e){} }
  } catch(e){}
  // 3) Profil client (toutes les fiches liées à cet UID)
  try {
    var comptes = await fbQueryEq('client_accounts', 'uid', uid) || [];
    var mines = comptes.filter(function(a){ return a && a.uid===uid && a.type==='particulier'; });
    if(SESSION.profileId && !mines.some(function(a){return a._id===SESSION.profileId;})) mines.push({ _id: SESSION.profileId });
    for(var j=0;j<mines.length;j++){ await fbDelete('client_accounts', mines[j]._id); }
  } catch(e){}
  // 4) Prévenir l'équipe (traçabilité)
  try { await fbPush('messages', _msgClientVersSupport({ type:'suppression_compte', client:SESSION.name, clientUser:SESSION.clientUser||'', email:SESSION.email||'', to:'staff', createdAt:new Date().toISOString(), lu:false }, '🗑️ Le client '+(SESSION.name||'')+' ('+(SESSION.email||'')+') a supprimé son compte.')); } catch(e){}
  // 5) Données locales + désabonnement des notifications
  try { ['mobilea_client_profil','mobilea_recurrences', clFavKey()].forEach(function(k){ localStorage.removeItem(k); }); } catch(e){}
  try { if(typeof window.mobileaUnlinkPush==='function') window.mobileaUnlinkPush(); } catch(e){}
  try { if(window.OneSignalDeferred) OneSignalDeferred.push(async function(OS){ try { await OS.logout(); } catch(e){} }); } catch(e){}
  // 6) Compte de connexion Firebase (en dernier)
  try { await user.delete(); }
  catch(e){
    if(btn){ btn.disabled=false; btn.textContent='Supprimer définitivement'; }
    setErr('Suppression du compte de connexion impossible : '+((e&&e.message)||e)+' — contactez MOBILEA.');
    return;
  }
  try { localStorage.removeItem(ADMIN_KEY); } catch(e){}
  viderCacheOffline();
  try { stopCoursesListener(); } catch(e){}
  try { stopMessagesListener(); } catch(e){}
  SESSION = { role:null, name:null, uid:null };
  window.SESSION = SESSION;
  ['cl-del-ov','cp-profil-ov'].forEach(function(id){ var x=document.getElementById(id); if(x) x.remove(); });
  document.getElementById('app').style.display='none';
  document.getElementById('login').style.display='flex';
  showToast('✓ Votre compte a été supprimé');
};

window.clPartagerParrainage = async function(){
  var code = clReferralCode();
  var txt = 'Réservez vos trajets avec MOBILEA et utilisez mon code parrainage '+code+' 🚗';
  try {
    if(navigator.share){ await navigator.share({ title:'MOBILEA', text:txt }); return; }
  } catch(e){}
  try { await navigator.clipboard.writeText(txt); showToast('Code copié : '+code); }
  catch(e){ showToast('Votre code : '+code); }
};

// Trajets récurrents (modèles stockés localement + rebooking 1 clic)
window.clRecRender = function(){
  var box=document.getElementById('cpf-rec-list'); if(!box) return;
  var list=clRecStore();
  if(!list.length){ box.innerHTML='<div style="color:var(--muted);font-size:13px;text-align:center;padding:10px">Aucun trajet récurrent. Ajoutez votre trajet habituel (ex. domicile → bureau).</div>'; return; }
  var J=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];
  box.innerHTML = list.map(function(r,i){
    return '<div style="background:var(--card2);border:1px solid var(--border2);border-radius:12px;padding:12px">'
      + '<div style="color:var(--white);font-weight:700;font-size:13px;margin-bottom:4px">'+E(r.dep||'')+' → '+E(r.arr||'')+'</div>'
      + '<div style="color:var(--muted);font-size:12px;margin-bottom:10px">'+ (r.jour!=null?J[r.jour]:'') +' · '+(r.heure||'')+' · '+(r.veh||'berline')+'</div>'
      + '<div style="display:flex;gap:6px">'
      +   '<button onclick="clRecBook('+i+')" style="flex:2;background:var(--gold);border:none;border-radius:9px;padding:9px;color:#111;font-weight:800;font-size:12px;cursor:pointer">Réserver</button>'
      +   '<button onclick="clRecDel('+i+')" style="flex:1;background:transparent;border:1px solid var(--border2);border-radius:9px;padding:9px;color:#e57373;font-size:12px;cursor:pointer">Supprimer</button>'
      + '</div></div>';
  }).join('');
};
