  var J=['Lun','Mar','Mer','Jeu','Ven','Sam','Dim'];
  ov.innerHTML =
      '<div style="background:var(--card);width:100%;max-width:420px;border-radius:16px;padding:20px">'
    +   '<div style="font-family:Inter,sans-serif;font-size:16px;font-weight:800;color:var(--white);margin-bottom:14px">🔁 Nouveau trajet récurrent</div>'
    +   '<div class="fld"><label>Départ</label><input type="text" id="clrec-dep" maxlength="200" placeholder="Ex. Domicile" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:10px;color:var(--white);font-size:13px;outline:none;box-sizing:border-box"></div>'
    +   '<div class="fld"><label>Arrivée</label><input type="text" id="clrec-arr" maxlength="200" placeholder="Ex. Bureau" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:10px;color:var(--white);font-size:13px;outline:none;box-sizing:border-box"></div>'
    +   '<div class="fg2" style="gap:10px">'
    +     '<div class="fld" style="margin:0"><label>Jour</label><select id="clrec-jour" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:10px;color:var(--white);font-size:13px;outline:none">'+J.map(function(j,n){return '<option value="'+n+'">'+j+'</option>';}).join('')+'</select></div>'
    +     '<div class="fld" style="margin:0"><label>Heure</label><input type="time" id="clrec-heure" value="08:00" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:10px;color:var(--white);font-size:13px;outline:none;box-sizing:border-box"></div>'
    +   '</div>'
    +   '<div class="fld"><label>Véhicule</label><select id="clrec-veh" style="width:100%;background:var(--dark);border:1px solid var(--border2);border-radius:10px;padding:10px;color:var(--white);font-size:13px;outline:none"><option value="berline">Berline</option><option value="van">Van</option><option value="sprinter">Sprinter</option></select></div>'
    +   '<div style="display:flex;gap:8px;margin-top:6px">'
    +     '<button onclick="document.getElementById(\'cl-rec-form-ov\').remove()" style="flex:1;background:var(--card2);border:1px solid var(--border2);border-radius:10px;padding:11px;color:var(--white);font-weight:700;cursor:pointer">Annuler</button>'
    +     '<button onclick="clRecSaveNew()" style="flex:2;background:var(--gold);border:none;border-radius:10px;padding:11px;color:#111;font-weight:800;cursor:pointer">Enregistrer</button>'
    +   '</div>'
    + '</div>';
  document.body.appendChild(ov);
  ov.onclick=function(e){ if(e.target===ov) ov.remove(); };
  setTimeout(function(){ try { ['clrec-dep','clrec-arr'].forEach(function(id){ var el=document.getElementById(id); if(el&&!el.dataset.placesReady) attachPlaces(id); }); } catch(e){} }, 200);
