window.clRecSaveNew = function(){
  var dep=(document.getElementById('clrec-dep').value||'').trim();
  var arr=(document.getElementById('clrec-arr').value||'').trim();
  if(!dep||!arr){ showToast('Départ et arrivée requis', true); return; }
  var r={ dep:dep, arr:arr, jour:parseInt(document.getElementById('clrec-jour').value)||0, heure:document.getElementById('clrec-heure').value||'08:00', veh:document.getElementById('clrec-veh').value||'berline' };
  var list=clRecStore(); list.push(r); clRecSave(list);
  var ov=document.getElementById('cl-rec-form-ov'); if(ov) ov.remove();
  clRecRender();
  showToast('🔁 Trajet récurrent enregistré');
};
window.clRecDel = function(i){ var a=clRecStore(); a.splice(i,1); clRecSave(a); clRecRender(); };
window.clRecBook = function(i){
  var r=clRecStore()[i]; if(!r) return;
  var ov=document.getElementById('cp-profil-ov'); if(ov) ov.remove();
  openClientBooking();
  setTimeout(function(){
    var dep=document.getElementById('cb-dep'), arr=document.getElementById('cb-arr');
    if(dep) dep.value=r.dep; if(arr) arr.value=r.arr;
    // Prochaine occurrence du jour choisi à l'heure choisie
    try {
      var now=new Date(); var target=new Date(now);
      var cur=(now.getDay()+6)%7; // 0=Lun
      var add=((r.jour - cur)+7)%7; if(add===0) add=7;
      target.setDate(now.getDate()+add);
      var hm=(r.heure||'08:00').split(':'); target.setHours(parseInt(hm[0])||8, parseInt(hm[1])||0, 0, 0);
      target.setMinutes(target.getMinutes()-target.getTimezoneOffset());
      var dtEl=document.getElementById('cb-dt'); if(dtEl) dtEl.value=target.toISOString().slice(0,16);
    } catch(e){}
    try { if(r.veh) cbSelectVeh(r.veh); else cbEstimatePrix(); } catch(e){}
    showToast('Trajet pré-rempli — vérifiez puis envoyez');
  }, 450);
};

// ── MODIFIER UNE RÉSERVATION CLIENT ──────────────────────────────────────
window.openEditBooking = function(courseId) {
  // Garde : un compte partenaire est en lecture seule (pas de modification)
  if(SESSION.type === 'partner' || window._clientType === 'partner') {
    showToast('Pour modifier une course, contactez MOBILEA (admin/dispatch).', true); return;
  }
  const c = D.courses.find(x => x._id === courseId);
  if(!c) { showToast('Course introuvable', true); return; }
  if(!['nouvelle','attribuee'].includes(c.statut)) {
    showToast('Cette course ne peut plus être modifiée', true); return;
  }
  document.getElementById('edit-course-id').value = courseId;
  document.getElementById('edit-dep').value = c.depart || '';
  document.getElementById('edit-arr').value = c.arrivee || '';
  document.getElementById('edit-pax').value = c.pax || 1;
  document.getElementById('edit-veh').value = c.vehicule || 'berline';
  document.getElementById('edit-vol').value = c.vol || '';
  document.getElementById('edit-notes').value = c.notes || '';
  document.getElementById('edit-err').textContent = '';
  // Formater la date pour datetime-local
  if(c.datetime) {
    const dt = new Date(c.datetime);
    dt.setMinutes(dt.getMinutes() - dt.getTimezoneOffset());
    document.getElementById('edit-dt').value = dt.toISOString().slice(0,16);
  }
  openMo('edit-booking');
  // Activer Places autocomplete sur les nouveaux champs
  setTimeout(function() {
    if(typeof google !== 'undefined' && google.maps && google.maps.places) {
      ['edit-dep','edit-arr'].forEach(function(id) {
        const el = document.getElementById(id);
        if(el && !el.dataset.placesReady) attachPlaces(id);
      });
    }
  }, 200);
};

window.submitEditBooking = async function() {
  const courseId = document.getElementById('edit-course-id').value;
  const dep = document.getElementById('edit-dep').value.trim();
  const arr = document.getElementById('edit-arr').value.trim();
  const dt = document.getElementById('edit-dt').value;
  const pax = parseInt(document.getElementById('edit-pax').value) || 1;
  const veh = document.getElementById('edit-veh').value;
  const vol = document.getElementById('edit-vol').value.trim();
  const notes = document.getElementById('edit-notes').value.trim();
  const errEl = document.getElementById('edit-err');
  errEl.textContent = '';

  if(!dep || !arr || !dt) { errEl.textContent = 'Départ, arrivée et date sont obligatoires'; return; }

  const c = D.courses.find(x => x._id === courseId);
  if(!c || !['nouvelle','attribuee'].includes(c.statut)) {
    errEl.textContent = 'Cette course ne peut plus être modifiée'; return;
  }

  try {
    await fbUpdate('courses', courseId, {
      depart: sanitize(dep, 200),
      arrivee: sanitize(arr, 200),
      datetime: new Date(dt).toISOString(),
      pax,
      vehicule: veh,
      vol: sanitize(vol, 20),
      notes: sanitize(notes, 300),
      modifiedByClient: SESSION.name,
      modifiedAt: new Date().toISOString(),
    });
    closeMo('edit-booking');
    showToast('✓ Réservation modifiée');
    await loadAll();
    renderClientPortal();
  } catch(e) {
    errEl.textContent = 'Erreur lors de la modification : ' + e.message;
  }
};

// ── RÉESSAYER UN PAIEMENT STRIPE ──────────────────────────────────────────
window.retryStripePayment = function(courseId) {
  const c = D.courses.find(x => x._id === courseId);
  if(!c) { showToast('Course introuvable', true); return; }
  const amount = c.prix || c.paiement_montant || 0;
  if(!amount) {
    showToast('Montant introuvable — contactez MOBILEA', true); return;
  }
  openStripePayment({
    courseId: c._id,
    clientName: SESSION.societe || SESSION.name || 'Client',
    amount: parseFloat(amount),
    desc: (c.depart || '') + ' → ' + (c.arrivee || ''),
  });
};

