  const fmt = p => p ? new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',minimumFractionDigits:2}).format(p) : '—';
  const prix = parseFloat(c.prix||0);
  // Ventilation TVA 10% (transport de personnes). Le prix stocké est TTC.
  const prixHT = prix / (1 + TVA);
  const prixTVA = prix - prixHT;
  const numRecu = 'REC-'+(c.ref||c._id.slice(0,6).toUpperCase());
  const dateCourse = fdt(c.datetime);
