  if(!list) return;
  const zones = await getZones();
  if(!zones.length) { list.innerHTML='<div style="text-align:center;color:var(--muted);font-size:12px;padding:20px">Aucune zone — les tarifs par défaut sont utilisés</div>'; return; }
