    + '<div style="font-size:44px;margin-bottom:6px">🚗</div>'
    + '<div style="font-family:Inter,sans-serif;font-size:20px;font-weight:800;color:#fff;margin-bottom:12px">Nouvelle réservation !</div>'
    + '<div style="display:inline-block;background:#b8860b;color:#111;font-weight:800;font-size:13px;padding:5px 14px;border-radius:20px;margin-bottom:14px">'+vI(course.vehicule)+'</div>'
    + '<div style="font-size:15px;color:#fff;font-weight:700;margin-bottom:10px">'+E(nomPassagerChauffeur(course))+'</div>'
    + '<div style="background:#2a2a2a;border-radius:12px;padding:14px;margin-bottom:14px;text-align:left">'
    +   '<div style="font-size:12px;color:#888;margin-bottom:3px">📍 Départ</div>'
    +   '<div style="font-size:14px;color:#fff;margin-bottom:10px">'+E(course.depart||course.lieu||'—')+'</div>'
    +   '<div style="font-size:12px;color:#888;margin-bottom:3px">🏁 Arrivée</div>'
    +   '<div style="font-size:14px;color:#fff">'+E(course.arrivee||course.duree||'—')+'</div>'
    + '</div>'
    + '<div style="font-size:13px;color:#aaa;margin-bottom:12px">🕐 '+dt+' • '+((course.pax||1))+' pax</div>'
    + prixHtml
    + '<div style="display:flex;gap:10px">'
    +   '<button onclick="document.getElementById(\'newresa-overlay\').remove()" style="flex:1;background:#3a3a3a;border:none;border-radius:12px;padding:15px;color:#fff;font-weight:700;font-size:14px;cursor:pointer">Plus tard</button>'
    +   '<button onclick="(function(){document.getElementById(\'newresa-overlay\').remove();openCourseFull(\''+course._id+'\');})()" style="flex:2;background:#22c55e;border:none;border-radius:12px;padding:15px;color:#fff;font-weight:800;font-size:15px;cursor:pointer;box-shadow:0 4px 14px rgba(34,197,94,0.4)">Voir la réservation ▸</button>'
    + '</div>'
