  var statutLbl = (typeof STATUT_LABELS!=='undefined') ? (STATUT_LABELS[c.statut]||c.statut) : c.statut;
  var body = '';
  try { body = window._buildDriverCourseCard ? window._buildDriverCourseCard(c, 0) : ''; }
  catch(e){ body = '<div style="padding:20px;color:#b00020">Erreur affichage : '+(e&&e.message)+'</div>'; }
  var ov = document.createElement('div');
  ov.id = 'coursefull-overlay';
  ov.style.cssText = 'position:fixed;inset:0;z-index:9999998;background:#f4f5f7;overflow-y:auto;-webkit-overflow-scrolling:touch';
