function toggleMob(){document.getElementById('sidebar').classList.toggle('on');document.getElementById('mob-ov').classList.toggle('on');}
// Swipe gestures comme Google Agenda
let touchStartX = 0;
document.addEventListener('touchstart', e => { touchStartX = e.touches[0].clientX; }, {passive:true});
document.addEventListener('touchend', e => {
  const dx = e.changedTouches[0].clientX - touchStartX;
  const sb = document.getElementById('sidebar');
  if(!sb) return;
  // Swipe droite depuis le bord gauche → ouvrir
  if(dx > 70 && touchStartX < 40 && !sb.classList.contains('on')) toggleMob();
  // Swipe gauche → fermer
  if(dx < -70 && sb.classList.contains('on')) closeMob();
}, {passive:true});
function closeMob(){document.getElementById('sidebar').classList.remove('on');document.getElementById('mob-ov').classList.remove('on');}
window.toggleMob=toggleMob;window.closeMob=closeMob;

