    + rgChamp('Supplément nuit (€ / h) <span style="font-weight:400;color:var(--muted)">vide = règle</span>', rgInp('rg-m-tn', r.tauxNuit)) + rgChamp('Date de début du contrat', rgInp('rg-m-dc', r.debutContrat, 'date')) + '</div>'
