  if (k === 'cmp' && v === 'perso' && (!RC.cmpDu || !RC.cmpAu)) { const p = rcPrec(RC.per, rcBornes(RC.per, RC.ref, RC.du, RC.au)); RC.cmpDu = p.du; RC.cmpAu = p.au; }
