function rcLigneTab(g, extra) { return [g.n, rgEur0(g.ht), rgEur0(g.tva), rgEur0(g.ttc), rgEur0(g.fact), rgEur0(g.enc), '<span style="color:' + (g.reste > 0.5 ? '#d97706' : 'inherit') + '">' + rgEur0(g.reste) + '</span>'].concat(extra || []); }
